#!/usr/bin/env zsh##################################################filename：ssh_port 授予执行权限#功能：本机端口通过跳板机转发到远程端口#执行方法：# ssh_port start 8080 10.10.2.2 80# ssh_port stop 8080# ssh_port status 8080#################################################check()&#123;    #验证参数是否为空    if [[ $&#123;#@&#125; &lt; 1 ]];then        echo &quot;请输入参数！&quot;        echo &quot;开启端口转发：ssh_port start 8080 10.10.2.2 80&quot;        echo &quot;关闭端口转发：ssh_port stop 8080&quot;        echo &quot;查看端口状态：ssh_port status 8080&quot;        exit 1    fi&#125;check $@# 工作目录WORKDIR=&quot;/Users/$(whoami)/workdir&quot;# 操作类型operation=&quot;$1&quot;# 本地端口local_port=&quot;$2&quot;# 远程 IP 地址remote_ip=&quot;$3&quot;# 远程端口remote_port=&quot;$4&quot;# SSH 控制套接字文件sock_file=&quot;$WORKDIR/$local_port.sock&quot;# 跳板机，~/.ssh/config中的配置jump_name=jump-machinestart()&#123;    echo &quot;start port begin........&quot;    pid=`port $local_port | grep ssh | awk &#x27;&#123;print $2&#125;&#x27;`    if [ -z &quot;$pid&quot; ] ; then        # 建立连接        ssh -nNT -S &quot;$sock_file&quot; -L 127.0.0.1:$local_port:$remote_ip:$remote_port $jump_name        echo &quot;ssh -nNT -S $&#123;sock_file&#125; -L 127.0.0.1:$&#123;local_port&#125;:$&#123;remote_ip&#125;:$&#123;remote_port&#125; $&#123;jump_name&#125;&quot;        echo &quot;start port success!&quot;        sleep 1    else        echo &quot;port is running.&quot;    fi&#125;stop()&#123;    echo &quot;stop port begin........&quot;    pid=`port $local_port | grep ssh | awk &#x27;&#123;print $2&#125;&#x27;`    if [ -z &quot;$pid&quot; ] ; then        echo &quot;No port running.&quot;    else        echo &quot;The port ($&#123;pid&#125;) is running...&quot;        # kill -9 $pid        ssh -S $sock_file -O exit $jump_name        echo &quot;ssh -S $sock_file -O exit $jump_name&quot;        echo &quot;stop port ($&#123;pid&#125;) success!&quot;    fi&#125;status()&#123;    echo &quot;check status port begin........&quot;    pid=`port $local_port | grep ssh | awk &#x27;&#123;print $2&#125;&#x27;`    if [ -z &quot;$pid&quot; ] ; then        echo &quot;No port running.&quot;    else        echo &quot;The port ($&#123;pid&#125;) is running...&quot;        port $local_port    fi&#125;if [ -n &quot;$operation&quot; ];then    # 判断操作类型    if [[ &quot;$operation&quot; == &quot;start&quot; ]]; then        # 建立连接        start    elif [[ &quot;$operation&quot; == &quot;stop&quot; ]]; then        # 关闭连接        stop    elif [[ &quot;$operation&quot; == &quot;status&quot; ]]; then        # 关闭连接        status    else        check        exit 1    fifi
