#!/usr/bin/env zsh##################################################filename：check_domain 授予执行权限#功能：检查域名到期时间#执行方法：check_domain baidu.com google.com#输出结果：# baidu.com，过期日期：2026-10-11# 距离到期还有958天# google.com，过期日期：2028-09-14# 距离到期还有1662天##################################################验证域名参数是否为空if [[ $&#123;#@&#125; &lt; 1 ]];then    echo &quot;请输入域名，多个域名空格分隔，如：check_domain baidu.com google.com&quot;fi#检测域名到期时间for domain in &quot;$@&quot;;do    #取出域名过期时间    expire_date=`whois $domain | grep &quot;Expiration Time&quot; | awk &#x27;&#123;print $3&#125;&#x27;`    if [ -z &quot;$expire_date&quot; ];then        expire_date=`whois $domain | grep &#x27;Expiry Date&#x27;| awk &#x27;&#123;print $4&#125;&#x27;| cut -d &#x27;T&#x27; -f 1`    fi    echo &quot;$&#123;domain&#125;，过期日期：$&#123;expire_date&#125;&quot;    #转换成时间戳    # 1.linux    # expire_date_timestamp=`date -d $expire_date +%s`    # 2.macos    # https://blog.csdn.net/zhw21w/article/details/126010972    expire_date_timestamp=`date -j -f %Y-%m-%d $expire_date +%s`    #以时间戳的形式显示当前时间    now=`date &#x27;+%s&#x27;`    #域名到期剩余天数    time_left=$[$[$expire_date_timestamp-$now]/86400]    echo &quot;距离到期还有$&#123;time_left&#125;天&quot;done
