#!/usr/bin/env zsh################################################## filename：ip-info 授权执行权限# 功能：查看IP信息# 使用方法：ip-info 10.10.2.24/24# 输出结果：#  网络地址: 10.10.2.0#  网关地址: 10.10.2.1#  广播地址: 10.10.2.255#  主机地址范围: 10.10.2.1 到 10.10.2.254# 也可以使用 sipcalc 命令，用法更多，显示也会更为详细：# 安装：brew install sipcalc# 使用示例：#  sipcalc 1.119.161.30/30#  sipcalc 10.10.2.32 255.255.255.0#  sipcalc 10.10.2.32 0xffffff00################################################## 检查是否提供了正确数量的参数if [ &quot;$#&quot; -ne 1 ]; then    echo &quot;用法: $0 &lt;IP地址/子网掩码CIDR&gt;&quot;    exit 1fi# 获取命令行参数ip_cidr=&quot;$1&quot;# 分割IP地址和子网掩码IFS=&#x27;/&#x27; read -A ip_parts &lt;&lt;&lt; &quot;$ip_cidr&quot;ip=$&#123;ip_parts[1]&#125;subnet_cidr=$&#123;ip_parts[2]&#125;# 计算子网掩码的二进制表示subnet_binary=$(printf &#x27;1%.0s&#x27; $(seq 1 &quot;$subnet_cidr&quot;) &amp;&amp; printf &#x27;0%.0s&#x27; $(seq 1 $((32 - $subnet_cidr))))# 将二进制子网掩码转换为点分十进制表示subnet_mask_decimal=$(printf &quot;%d.%d.%d.%d&quot; $((2#$&#123;subnet_binary:0:8&#125;)) $((2#$&#123;subnet_binary:8:8&#125;)) $((2#$&#123;subnet_binary:16:8&#125;)) $((2#$&#123;subnet_binary:24:8&#125;)))# 使用按位与运算计算网络地址network_address=$(printf &quot;%d.%d.%d.%d&quot; $(( $(echo $ip | cut -d. -f1) &amp; $(echo $subnet_mask_decimal | cut -d. -f1) )) $(( $(echo $ip | cut -d. -f2) &amp; $(echo $subnet_mask_decimal | cut -d. -f2) )) $(( $(echo $ip | cut -d. -f3) &amp; $(echo $subnet_mask_decimal | cut -d. -f3) )) $(( $(echo $ip | cut -d. -f4) &amp; $(echo $subnet_mask_decimal | cut -d. -f4) )))# 计算广播地址和网关地址broadcast_address=$(printf &quot;%d.%d.%d.%d&quot; $(( $(echo $network_address | cut -d. -f1) | (255 - $(echo $subnet_mask_decimal | cut -d. -f1) % 256) )) $(( $(echo $network_address | cut -d. -f2) | (255 - $(echo $subnet_mask_decimal | cut -d. -f2) % 256) )) $(( $(echo $network_address | cut -d. -f3) | (255 - $(echo $subnet_mask_decimal | cut -d. -f3) % 256) )) $(( $(echo $network_address | cut -d. -f4) | (255 - $(echo $subnet_mask_decimal | cut -d. -f4) % 256) )))gateway_address=$(printf &quot;%d.%d.%d.%d&quot; $(echo $network_address | cut -d. -f1) $(echo $network_address | cut -d. -f2) $(echo $network_address | cut -d. -f3) $(( $(echo $network_address | cut -d. -f4) + 1)))# 输出结果echo &quot;网络地址: $network_address&quot;echo &quot;网关地址: $gateway_address&quot;echo &quot;广播地址: $broadcast_address&quot;# 计算主机地址范围first_host=$(printf &quot;%d.%d.%d.%d&quot; $(echo $network_address | cut -d. -f1) $(echo $network_address | cut -d. -f2) $(echo $network_address | cut -d. -f3) $(( $(echo $network_address | cut -d. -f4) + 1)))last_host=$(printf &quot;%d.%d.%d.%d&quot; $(echo $broadcast_address | cut -d. -f1) $(echo $broadcast_address | cut -d. -f2) $(echo $broadcast_address | cut -d. -f3) $(( $(echo $broadcast_address | cut -d. -f4) - 1)))echo &quot;主机地址范围: $first_host 到 $last_host&quot;
