#!/usr/bin/env zsh##################################################filename：jdk_version#功能：获取对应java文件的jdk编译版本# 如果是jar，这里只会检索jar包中第一个class的jdk编译版本，所以也不一定准确##执行方法：jdk_version &lt;file_path:[.jar|.class|.war]&gt;# 1.jar示例：#  jdk_version xxl-job-admin-2.3.0.jar# 输出：#  Build-Jdk: 1.8.0_271#  file_path:[xxl-job-admin-2.3.0.jar]	major_version:[52]	jdk_version:[jdk1.8]# 2.class示例#  jdk_version XxlJobAdminConfig.class# 输出：#  file_path:[XxlJobAdminConfig.class]	major_version:[52]	jdk_version:[jdk1.8]# 3.war示例#  jdk_version wardir/BOSS.war# 输出：#  file_path:[wardir/BOSS.war]		jdk_version:[1.7.0_67-b01 (Oracle Corporation)]################################################## 定义关联数组typeset -A my_map# 向关联数组中添加键值对# LTS:#    8(2014年初发布，免费版本至8u202，从8u211开始商用收费，支持到2030年9月)#    11(2018年9月发布，免费版本版本至11.0.2，后续版本商用收费，支持到2032年9月)#    17(2021年9月发布，免费，支持到2029年9月)#    21(2023年9月发布，免费，支持到2031年9月)#    25(预计2025年9月发布，支持到2033年9月)# 后续Oracle计划每半年发布一个新的大版本(3、9月)，每两年发布一次LTS(9月)，建议正式环境只使用LTS版本# 此处可以查看jdk发布计划：https://www.java.com/en/releases/matrix/# JDK下载地址：https://www.oracle.com/cn/java/technologies/downloads/my_map=(    [45]=&quot;jdk1.1&quot;    [46]=&quot;jdk1.2&quot;    [47]=&quot;jdk1.3&quot;    [48]=&quot;jdk1.4&quot;    [49]=&quot;jdk1.5&quot;    [50]=&quot;jdk1.6&quot;    [51]=&quot;jdk1.7&quot;    [52]=&quot;jdk1.8&quot;    [53]=&quot;jdk9&quot;    [54]=&quot;jdk10&quot;    [55]=&quot;jdk11&quot;    [56]=&quot;jdk12&quot;    [57]=&quot;jdk13&quot;    [58]=&quot;jdk14&quot;    [59]=&quot;jdk15&quot;    [60]=&quot;jdk16&quot;    [61]=&quot;jdk17&quot;    [62]=&quot;jdk18&quot;    [63]=&quot;jdk19&quot;    [64]=&quot;jdk20&quot;    [65]=&quot;jdk21&quot;    [66]=&quot;jdk22&quot;    [67]=&quot;jdk23&quot;    [68]=&quot;jdk24&quot;    [69]=&quot;jdk25&quot;)# 获取所有键并排序sorted_keys=($&#123;(o)$&#123;(k)my_map&#125;&#125;)# echo $sorted_keysoriginal_string=&quot;\tmajor_version\tjdk_version&quot;# tr &#x27;[:lower:]&#x27; &#x27;[:upper:]&#x27; 将字符串中的小写字母转换为大写字母。输出结果将是 &quot;MAJOR_VERSION\tJDK_VERSION&quot;uppercase_string=$(echo &quot;$original_string&quot; | tr &#x27;[:lower:]&#x27; &#x27;[:upper:]&#x27;)# 打印mapecho_map() &#123;    echo &quot;$&#123;uppercase_string&#125;&quot;    # 按排序后的键输出键值对    for key in $sorted_keys; do        echo &quot;\t$key\t\t$&#123;my_map[$key]&#125;&quot;    done&#125;error_message() &#123;    echo &quot;Usage: jdk_version &lt;file_path:[.jar|.class|.war]&gt;&quot;    echo_map    exit 1&#125;# 检查是否传递了参数if [ -z &quot;$1&quot; ]; then    error_messagefifile_path=$1# 检查文件是否存在if [ ! -e &quot;$file_path&quot; ]; then    echo &quot;文件不存在:file_path:[$&#123;file_path&#125;]&quot;    error_messagefigreap_content=&quot;major version&quot;if [[ $file_path == *.class ]]; then    # 通过javap命令获取class文件的详细信息，grep过滤出包含 “major version” 的行，awk取出其版本号    key=$(javap -verbose $&#123;file_path&#125; | grep &quot;$&#123;greap_content&#125;&quot; | awk -F&#x27;: &#x27; &#x27;&#123;print $2&#125;&#x27;)elif [[ $file_path == *.jar ]]; then    # 先通过“jar tf”命令获取jar包中的class文件，这里只取出第一个，注意这里class路径必须去掉“.class”，之后再通过javap命令获取“-classpath”所指定的jar中的这个第一个class文件的详细信息，grep过滤出包含 “major version” 的行，awk取出其版本号    key=$(javap -classpath $&#123;file_path&#125; -verbose $(jar tf $&#123;file_path&#125; | grep &quot;.class$&quot; | head -n 1 | sed s/.class//) | grep &quot;$&#123;greap_content&#125;&quot; | awk -F&#x27;: &#x27; &#x27;&#123;print $2&#125;&#x27;)    # 通过jar包中的MANIFEST.MF文件来判断打包的jdk版本    result=$(unzip -p $&#123;file_path&#125; $(jar tf $&#123;file_path&#125; | grep &quot;MANIFEST.MF$&quot; | head -n 1) | grep &quot;^Build-Jdk&quot;)    if [ -z &quot;$result&quot; ]; then        result=$(unzip -p $&#123;file_path&#125; $(jar tf $&#123;file_path&#125; | grep &quot;MANIFEST.MF$&quot; | head -n 1) | grep &quot;^Created-By&quot;)    fi    if [ -n &quot;$result&quot; ]; then        echo $result    else        echo &quot;没有在 MANIFEST.MF 中发现jdk相关信息&quot;    fielif [[ $file_path == *.war ]]; then    # 查找 Build-Jdk    jdk_version=$(unzip -p &quot;$&#123;file_path&#125;&quot; META-INF/MANIFEST.MF | grep -i &quot;^Build-Jdk&quot; | awk -F&#x27;: &#x27; &#x27;&#123;print $2&#125;&#x27;)    # 如果 Build-Jdk 未找到，则尝试查找 Created-By    if [ -z &quot;$jdk_version&quot; ]; then        jdk_version=$(unzip -p &quot;$&#123;file_path&#125;&quot; META-INF/MANIFEST.MF | grep -i &quot;^Created-By&quot; | awk -F&#x27;: &#x27; &#x27;&#123;print $2&#125;&#x27;)    fielse    error_messagefi# 打印结果# 输出 JDK 版本信息if [ -n &quot;$key&quot; ]; then    echo &quot;file_path:[$&#123;file_path&#125;]\tmajor_version:[$key]\tjdk_version:[$&#123;my_map[$key]&#125;]&quot;elif [ -n &quot;$jdk_version&quot; ]; then    # jdk_version含有特殊字符，通过如下命令查看包含哪些特殊字符，结果发现包含\r\n    # echo &quot;$&#123;jdk_version&#125;&quot; | od -c    # 去掉特殊字符 \r\n    jdk_version_cleaned=$(echo &quot;$&#123;jdk_version&#125;&quot; | tr -d &#x27;\r\n&#x27;)    echo  &quot;file_path:[$&#123;file_path&#125;]\t\tjdk_version:[$&#123;jdk_version_cleaned&#125;]&quot;else    echo &quot;JDK Version information not found&quot;fi

