package com.example.r2dbc;import io.r2dbc.proxy.core.QueryExecutionInfo;import io.r2dbc.proxy.listener.ProxyMethodExecutionListener;import io.r2dbc.proxy.support.QueryExecutionInfoFormatter;import lombok.extern.slf4j.Slf4j;@Slf4jpublic class LogExecutionListener implements ProxyMethodExecutionListener &#123;    private final QueryExecutionInfoFormatter queryFormatter = new QueryExecutionInfoFormatter()            .newLine()            .showTime().showType().showSuccess().showTransaction().showBatchSize().showConnection().showThread()            .newLine()            .showQuery()            .newLine()            .showBindingsSize().showBindings()            .newLine();    @Override    public void afterExecuteOnStatement(QueryExecutionInfo queryExecutionInfo) &#123;        String stringBuilder = this.queryFormatter.format(queryExecutionInfo);        log.info(stringBuilder);    &#125;&#125;
条件查询


springboot为我们提供了几个Repository，如R2dbcRepository、ReactiveCrudRepository、ReactiveSortingRepository等等，我们自己的Repository通过继承这些父接口，可以获得相应的CURD的能力，但是其没有对条件查询提供支持，此时可以通过自定义Repository接口及其实现类的方式实现扩展


自定义Repository接口


package com.example.r2dbc;import io.r2dbc.spi.Row;import io.r2dbc.spi.RowMetadata;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.data.r2dbc.core.R2dbcEntityOperations;import org.springframework.data.r2dbc.repository.R2dbcRepository;import org.springframework.data.relational.core.query.Criteria;import org.springframework.data.relational.core.query.Query;import org.springframework.data.repository.NoRepositoryBean;import org.springframework.r2dbc.core.DatabaseClient;import reactor.core.publisher.Flux;import reactor.core.publisher.Mono;import java.io.Serializable;import java.util.Map;import java.util.function.BiFunction;@NoRepositoryBean //接口不参与jpa的代理public interface BaseR2dbcRepository&lt;T, ID extends Serializable&gt; extends R2dbcRepository&lt;T, ID&gt; &#123;    R2dbcEntityOperations getR2dbcEntityOperations();    /**     * 分页查询     */    Mono&lt;Page&lt;T&gt;&gt; pageByQuery(Criteria criteria, Pageable pageable);    Mono&lt;Long&gt; countByQuery(Criteria criteria);    Flux&lt;T&gt; findByQuery(Criteria criteria);    Flux&lt;T&gt; findByQuery(Criteria criteria, Sort sort);    Flux&lt;T&gt; findByQuery(Criteria criteria, int limit);    Flux&lt;T&gt; findByQuery(Criteria criteria, Sort sort, int limit);    Flux&lt;T&gt; findByQuery(Query query);    Mono&lt;T&gt; findOneByQuery(Query query);    Mono&lt;T&gt; findOneByQuery(Criteria criteria);    default &lt;R&gt; Mono&lt;R&gt; execSqlToMono(String sql, Map&lt;String, Object&gt; bindMap, BiFunction&lt;Row, RowMetadata, R&gt; mappingFunction) &#123;        DatabaseClient.GenericExecuteSpec genericExecuteSpec = getR2dbcEntityOperations().getDatabaseClient().sql(sql);        if (bindMap != null) &#123;            for (Map.Entry&lt;String, Object&gt; entry : bindMap.entrySet()) &#123;                genericExecuteSpec = genericExecuteSpec.bind(entry.getKey(), entry.getValue());            &#125;        &#125;        return genericExecuteSpec.map(mappingFunction).first();    &#125;    default &lt;R&gt; Flux&lt;R&gt; execSqlToFlux(String sql, Map&lt;String, Object&gt; bindMap, BiFunction&lt;Row, RowMetadata, R&gt; mappingFunction) &#123;        DatabaseClient.GenericExecuteSpec genericExecuteSpec = getR2dbcEntityOperations().getDatabaseClient().sql(sql);        if (bindMap != null) &#123;            for (Map.Entry&lt;String, Object&gt; entry : bindMap.entrySet()) &#123;                genericExecuteSpec = genericExecuteSpec.bind(entry.getKey(), entry.getValue());            &#125;        &#125;        return genericExecuteSpec.map(mappingFunction).all();    &#125;&#125;


自定义Repository接口的实现类


package com.example.r2dbc;import lombok.extern.slf4j.Slf4j;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageImpl;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.data.r2dbc.convert.R2dbcConverter;import org.springframework.data.r2dbc.core.R2dbcEntityOperations;import org.springframework.data.r2dbc.repository.support.SimpleR2dbcRepository;import org.springframework.data.relational.core.query.Criteria;import org.springframework.data.relational.core.query.Query;import org.springframework.data.relational.repository.query.RelationalEntityInformation;import reactor.core.publisher.Flux;import reactor.core.publisher.Mono;import java.io.Serializable;@Slf4jpublic class SimpleBaseR2dbcRepository&lt;T, ID extends Serializable&gt; extends SimpleR2dbcRepository&lt;T, ID&gt; implements BaseR2dbcRepository&lt;T, ID&gt; &#123;    private final R2dbcEntityOperations r2dbcEntityOperations;    private final RelationalEntityInformation&lt;T, ID&gt; entity;    public SimpleBaseR2dbcRepository(RelationalEntityInformation&lt;T, ID&gt; entity, R2dbcEntityOperations entityOperations, R2dbcConverter converter) &#123;        super(entity, entityOperations, converter);        this.r2dbcEntityOperations = entityOperations;        this.entity = entity;        log.info(&quot;SimpleBaseR2dbcRepository&quot;);    &#125;    @Override    public R2dbcEntityOperations getR2dbcEntityOperations() &#123;        return r2dbcEntityOperations;    &#125;    @Override    public Mono&lt;Page&lt;T&gt;&gt; pageByQuery(Criteria criteria, Pageable pageable) &#123;        final Query query = Query.query(criteria);        return r2dbcEntityOperations.count(query, entity.getJavaType()).flatMap(total -&gt;                r2dbcEntityOperations.select(query.with(pageable), entity.getJavaType())                        .collectList()                        .map(list -&gt; new PageImpl&lt;&gt;(list, pageable, total)));    &#125;    @Override    public Mono&lt;Long&gt; countByQuery(Criteria criteria) &#123;        final Query query = Query.query(criteria);        return r2dbcEntityOperations.count(query, entity.getJavaType());    &#125;    @Override    public Flux&lt;T&gt; findByQuery(Criteria criteria) &#123;        final Query query = Query.query(criteria);        return r2dbcEntityOperations.select(query, entity.getJavaType());    &#125;    @Override    public Flux&lt;T&gt; findByQuery(Criteria criteria, Sort sort) &#123;        final Query query = Query.query(criteria).sort(sort);        return r2dbcEntityOperations.select(query, entity.getJavaType());    &#125;    @Override    public Flux&lt;T&gt; findByQuery(Criteria criteria, int limit) &#123;        final Query query = Query.query(criteria).limit(limit);        return r2dbcEntityOperations.select(query, entity.getJavaType());    &#125;    @Override    public Flux&lt;T&gt; findByQuery(Criteria criteria, Sort sort, int limit) &#123;        final Query query = Query.query(criteria).sort(sort).limit(limit);        return r2dbcEntityOperations.select(query, entity.getJavaType());    &#125;    @Override    public Flux&lt;T&gt; findByQuery(Query query) &#123;        return r2dbcEntityOperations.select(query, entity.getJavaType());    &#125;    @Override    public Mono&lt;T&gt; findOneByQuery(Query query) &#123;        return r2dbcEntityOperations.selectOne(query, entity.getJavaType());    &#125;    @Override    public Mono&lt;T&gt; findOneByQuery(Criteria criteria) &#123;        final Query query = Query.query(criteria);        return r2dbcEntityOperations.selectOne(query, entity.getJavaType());    &#125;&#125;


我们需要告知springboot使用我们自定义的Repository


package com.example.config;import com.example.r2dbc.SimpleBaseR2dbcRepository;import lombok.extern.slf4j.Slf4j;import org.springframework.context.annotation.Configuration;import org.springframework.data.r2dbc.repository.config.EnableR2dbcRepositories;@Slf4j@Configuration// 这里必须指定 basePackages，否则 repositoryBaseClass 指定的实现类不能被关联到 各个 Repository 中@EnableR2dbcRepositories(basePackages = &quot;com.example.mysql&quot;, repositoryBaseClass = SimpleBaseR2dbcRepository.class)public class ReactiveR2dbcConfig &#123;&#125;


此时我们在创建业务Repository时就可以继承我们自定义的Repository了


public interface SysUserRepository extends BaseR2dbcRepository&lt;SysUser, String&gt; &#123;&#125;


可以看到我们自定义的Repository中，主要是通过Criteria来提供查询条件的封装，我了便于创建Criteria对象，这里提供了一个工具类 CustomCriteria，其主要功能是根据条件来拼接查询条件，代码比较多，就不在这里粘贴了，自行去Github代码地址中查看吧。


/** * &lt;h1&gt;CustomCriteria&lt;/h1&gt; * Criteria 构造器 * Created by hanqf on 2023/9/4 11:47. * * * 示例： * 1.and 关系: select * from tbl_table where (username like &#x27;%admin%&#x27; or username like &#x27;lisi%&#x27;) and enable = 1 * Criteria criteria = CustomCriteria.and() *                 .like(true, &quot;username&quot;, &quot;%admin%&quot;, &quot;lisi%&quot;) *                 .eq(true, &quot;enable&quot;, 1) *                 .build(); * * 2.or 关系: select * from tbl_table where (username like &#x27;%admin%&#x27; or username like &#x27;lisi%&#x27;) or enable = 1 * Criteria criteria = CustomCriteria.or() *                 .like(true, &quot;username&quot;, &quot;%admin%&quot;, &quot;lisi%&quot;) *                 .eq(true, &quot;enable&quot;, 1) *                 .build(); * * 3.复合关系： * Criteria criteria1 = CustomCriteria.and() *                 .like(true, &quot;username&quot;, &quot;%admin%&quot;, &quot;lisi%&quot;) *                 .eq(true, &quot;enable&quot;, 1) *                 .build(); * Criteria criteria2 = CustomCriteria.or() *                 .like(true, &quot;username&quot;, &quot;%admin%&quot;, &quot;lisi%&quot;) *                 .eq(true, &quot;enable&quot;, 1) *                 .build(); * * Criteria criteria = criteria1.and(criteria2);  // or： criteria1.or(criteria2); * * 4.复杂查询建议直接使用 sql 进行查询，可以使用  BaseR2dbcRepository 中的 execSqlToMono 和 execSqlToFlux * 示例： *  public Mono&lt;TestOrder&gt; getOne(String orderId) &#123;        String sql = &quot;select id, order_id from test_order where order_id = :orderId&quot;;        return testOrderRepository.execSqlToMono(sql, Map.of(&quot;orderId&quot;, orderId), (row, rowMetadata) -&gt; &#123;            final TestOrder testOrder = new TestOrder();            testOrder.setId(row.get(&quot;id&quot;, Long.class));            testOrder.setOrderId(row.get(&quot;order_id&quot;, String.class));            return testOrder;        &#125;);    &#125; * * * 说明： * 1.eq(true, &quot;enable&quot;, 1)：第一个参数为真时当前条件加入查询，默认为真 * 2.支持条件方法详见代码 */
新增


R2dbc提供的&lt;S extends T&gt; Mono&lt;S&gt; save(S entity);方法，要求table必须含有主键，其根据实体类中主键是否被填充来判断是新增还是修改操作，如果我们是自定义主键，而非数据库自动填充主键，此时就不能使用save方法新增记录，解决方法是在业务Repository中创建一个新增方法，比如：


/** * 实体类在进行新增时会判断主键是否填充，如果没有填充就认为是新数据，采取真正的新增操作，主键需要数据库来自动填充； * 如果主键存在值则认为是旧数据则调用更新操作。 * 对于自定义主键的情况，可以使用如下方式进行新增对象 * * 对象形式传参：:#&#123;#对象名.字段名&#125; * 字段传参：:字段名(@param定义)*/@Modifying@Query(&quot;insert into sys_user (id,username,password,enable) values (:#&#123;#sysUser.id&#125;,:#&#123;#sysUser.username&#125;,:#&#123;#sysUser.password&#125;,:#&#123;#sysUser.enable&#125;)&quot;)Mono&lt;Integer&gt; addSysUser(SysUser sysUser);
事务


注解式事务


@Transactional@RequestMapping(&quot;/tx&quot;)public Mono&lt;Integer&gt; tx() &#123;    final SysUser sysUser = new SysUser();    sysUser.setId(UUID.randomUUID().toString());    sysUser.setUsername(&quot;test&quot;);    sysUser.setPassword(&quot;123456&quot;);    sysUser.setEnable(true);    // 主键重复    return sysUserRepository.addSysUser(sysUser).then(sysUserRepository.addSysUser(sysUser));&#125;


编程式事务


@Autowiredprivate TransactionalOperator transactionalOperator;@RequestMapping(&quot;/tx2&quot;)public Mono&lt;Integer&gt; tx2() &#123;    final SysUser sysUser = new SysUser();    sysUser.setId(UUID.randomUUID().toString());    sysUser.setUsername(&quot;test&quot;);    sysUser.setPassword(&quot;123456&quot;);    sysUser.setEnable(true);    // 主键重复    return sysUserRepository.addSysUser(sysUser).then(sysUserRepository.addSysUser(sysUser))            .as(transactionalOperator::transactional);&#125;
