one:配置类


package com.example.config;import com.example.r2dbc.SimpleBaseR2dbcRepository;import io.r2dbc.spi.ConnectionFactories;import io.r2dbc.spi.ConnectionFactory;import io.r2dbc.spi.ConnectionFactoryOptions;import io.r2dbc.spi.Option;import lombok.extern.slf4j.Slf4j;import org.springframework.boot.autoconfigure.r2dbc.R2dbcProperties;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.Primary;import org.springframework.data.r2dbc.core.R2dbcEntityTemplate;import org.springframework.data.r2dbc.repository.config.EnableR2dbcRepositories;import org.springframework.r2dbc.connection.R2dbcTransactionManager;import org.springframework.transaction.ReactiveTransactionManager;import org.springframework.transaction.TransactionDefinition;import org.springframework.transaction.reactive.TransactionalOperator;import org.springframework.transaction.support.DefaultTransactionDefinition;import org.springframework.util.StringUtils;import java.util.function.Predicate;import java.util.function.Supplier;@Slf4j@Configuration// 这里必须指定 basePackages，否则 repositoryBaseClass 指定的实现类不能被关联到 各个 Repository 中@EnableR2dbcRepositories(basePackages = &quot;com.example.mysql.one.repository&quot;, repositoryBaseClass = SimpleBaseR2dbcRepository.class, entityOperationsRef = &quot;oneR2dbcEntityTemplate&quot;)public class OneReactiveR2dbcConfig &#123;    @Primary    @Bean(&quot;oneR2dbcProperties&quot;)    @ConfigurationProperties(prefix = &quot;spring.r2dbc.one&quot;)    public R2dbcProperties oneR2dbcProperties() &#123;        return new R2dbcProperties();    &#125;    @Primary    @Bean(&quot;oneR2dbcEntityTemplate&quot;)    public R2dbcEntityTemplate oneR2dbcEntityTemplate() &#123;        log.info(&quot;oneR2dbcEntityTemplate&quot;);        return new R2dbcEntityTemplate(oneConnectionFactory());    &#125;    @Primary    @Bean(&quot;oneConnectionFactory&quot;)    public ConnectionFactory oneConnectionFactory() &#123;        log.info(&quot;oneConnectionFactory&quot;);        R2dbcProperties r2dbcProperties = oneR2dbcProperties();        ConnectionFactoryOptions urlOptions = ConnectionFactoryOptions.parse(r2dbcProperties.getUrl());        ConnectionFactoryOptions.Builder optionsBuilder = urlOptions.mutate();        configureIf(optionsBuilder, urlOptions, ConnectionFactoryOptions.USER, r2dbcProperties::getUsername,                StringUtils::hasText);        configureIf(optionsBuilder, urlOptions, ConnectionFactoryOptions.PASSWORD, r2dbcProperties::getPassword,                StringUtils::hasText);        configureIf(optionsBuilder, urlOptions, ConnectionFactoryOptions.DATABASE,                () -&gt; determineDatabaseName(r2dbcProperties), StringUtils::hasText);        if (r2dbcProperties.getProperties() != null) &#123;            r2dbcProperties.getProperties()                    .forEach((key, value) -&gt; optionsBuilder.option(Option.valueOf(key), value));        &#125;        final ConnectionFactoryOptions options = optionsBuilder.build();        return ConnectionFactories.get(options);    &#125;    @Primary    @Bean(&quot;oneR2dbcTransactionManager&quot;)    public ReactiveTransactionManager oneR2dbcTransactionManager() &#123;        return new R2dbcTransactionManager(oneConnectionFactory());    &#125;    @Primary    @Bean(&quot;oneTransactionalOperator&quot;)    public TransactionalOperator oneTransactionalOperator() &#123;        DefaultTransactionDefinition transactionDefinition = new DefaultTransactionDefinition();        transactionDefinition.setName(&quot;oneTransactionalOperator&quot;);        // 这是默认行为        transactionDefinition.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED);        return TransactionalOperator.create(oneR2dbcTransactionManager(), transactionDefinition);    &#125;    private &lt;T extends CharSequence&gt; void configureIf(ConnectionFactoryOptions.Builder optionsBuilder,                                                      ConnectionFactoryOptions originalOptions, Option&lt;T&gt; option, Supplier&lt;T&gt; valueSupplier,                                                      Predicate&lt;T&gt; setIf) &#123;        if (originalOptions.hasOption(option)) &#123;            return;        &#125;        T value = valueSupplier.get();        if (setIf.test(value)) &#123;            optionsBuilder.option(option, value);        &#125;    &#125;    private String determineDatabaseName(R2dbcProperties properties) &#123;        if (properties.isGenerateUniqueName()) &#123;            return properties.determineUniqueName();        &#125;        if (StringUtils.hasLength(properties.getName())) &#123;            return properties.getName();        &#125;        return null;    &#125;&#125;


