public interface CountryJpaRepository extends BaseJpaRepository&lt;Country, Long&gt; &#123;    //sql查询，只有SELECT * 时才可以直接返回@Entity对象，但要有无参构造方法，page要指定countQuery    @Query(value = &quot;SELECT * FROM tbl_country WHERE id &gt; ?1&quot;, countQuery = &quot;SELECT count(*) FROM tbl_country WHERE id &gt; ?1&quot;, nativeQuery = true)    Page&lt;Country&gt; findByIdAfter(Long id, Pageable pageable);    //sql查询，只有SELECT * 时才可以直接返回@Entity对象    @Query(value = &quot;SELECT * FROM tbl_country  WHERE name_zh = ?1&quot;,nativeQuery = true)    Country findCountrySqlByName(String name);    //hql查询部分属性时，返回@Entity对象，要在@Entity中创建对应的构造方法    @Query(value = &quot;SELECT new Country(id,nameZh,nameEn) FROM Country WHERE nameZh = ?1&quot;)    Country findCountryHqlByName(String name);    //hql查询部分属性时，返回非@Entity对象，要创建对应的构造方法，且必须使用全路径    @Query(value = &quot;SELECT new com.example.demo.CountryDto(id,nameZh,nameEn) FROM Country WHERE nameZh = ?1&quot;)    CountryDto findCountryDtoNewHqlByName(String name);&#125;
说明


返回@Entity对象，查询全部属性时，sql和hql都支持直接转换


返回@Entity对象，查询部分属性时，sql不支持直接转换，hql时，实体要有对应的构造方法


hql也可以返回Dto对象，查询部分属性时，同样需要Dto有对应的构造方法，注意Dto必须使用全路径


sql查询部分属性直接转换成对象的方法


方法1，前一篇文章Spring Boot自定义JpaRepository基类中通过自定义JpaRepository基类，转换@Entity对象和Dto对象都支持


方法2，注入自定义的结果转换器，只能转换为Dto对象，下面说明如何实现


注入自定义的结果转换器


无论是sql还是hql，查询部分属性时，jpa输出的结果都会被转化为Map对象，我们只需要注入一个能将Map转换为指定对象的转换器就可以了


/** * &lt;h1&gt;注入自定义查询结果转换器&lt;/h1&gt; */@Slf4j@Configurationpublic class JpaDtoConfig &#123;    @Autowired    private ApplicationContext applicationContext;    //这里用到了上文“Spring Boot自定义JpaRepository基类”中介绍过的JpaUtil，通过json作为中间媒介    @Autowired    private JpaUtil jpaUtil;    /**     * 初始化注入@JpaDto对应的Converter     */    @PostConstruct    public void init() &#123;        Map&lt;String, Object&gt; map = applicationContext.getBeansWithAnnotation(JpaDto.class);        for (Object o : map.values()) &#123;            Class c = o.getClass();            log.info(&quot;Jpa添加Converter,class=&#123;&#125;&quot;, c.getName());            DefaultConversionService defaultConversionService = ((DefaultConversionService) DefaultConversionService.getSharedInstance());            //添加Map对象的转换器，将Map对象转换为指定的对象类型            defaultConversionService.addConverter(Map.class, c, m -&gt; &#123;                try &#123;                    return jpaUtil.mapToObject(m, c, false);                &#125; catch (Exception e) &#123;                    throw new FatalBeanException(&quot;Jpa结果转换出错,class=&quot; + c.getName(), e);                &#125;            &#125;);        &#125;    &#125;&#125;


