package com.example.oauth2resourceserverwebfluxdemo.config;import com.example.oauth2resourceserverwebfluxdemo.security.CustomReactiveAuthorizationManager;import com.example.oauth2resourceserverwebfluxdemo.security.CustomServerAccessDeniedHandler;import com.example.oauth2resourceserverwebfluxdemo.security.CustomServerAuthenticationEntryPoint;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.config.annotation.method.configuration.EnableReactiveMethodSecurity;import org.springframework.security.config.web.server.ServerHttpSecurity;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.web.server.SecurityWebFilterChain;import reactor.core.publisher.Mono;import java.util.Collection;import java.util.stream.Collectors;/** * &lt;h1&gt;安全认证配置&lt;/h1&gt; * Created by hanqf on 2020/11/19 10:26. */@Configuration//@EnableWebFluxSecurity //非必要@EnableReactiveMethodSecurity //启用@PreAuthorize注解配置public class ReactiveSecurityConfig &#123;    @Autowired    private CustomServerAccessDeniedHandler customServerAccessDeniedHandler;    @Autowired    private CustomServerAuthenticationEntryPoint customServerAuthenticationEntryPoint;    @Autowired    private CustomReactiveAuthorizationManager customReactiveAuthorizationManager;    /**     * 注册安全验证规则     * 配置方式与HttpSecurity基本一致     */    @Bean    SecurityWebFilterChain springSecurityFilterChain(ServerHttpSecurity http) &#123; //定义SecurityWebFilterChain对安全进行控制，使用ServerHttpSecurity构造过滤器链；        return http.authorizeExchange()                //.anyExchange().authenticated() //所有请求都需要通过认证                .pathMatchers(&quot;/res/**&quot;, &quot;/userInfo/**&quot;).authenticated()                //需要具备相应的角色才能访问                .pathMatchers(&quot;/user/**&quot;).hasAnyRole(&quot;admin&quot;, &quot;user&quot;)                //不需要登录就可以访问                .pathMatchers(&quot;/swagger-ui/**&quot;, &quot;/v3/api-docs**&quot;).permitAll()                //其它路径需要根据指定的方法判断是否有权限访问，基于权限管理模型认证                .anyExchange().access(customReactiveAuthorizationManager)                .and()                .csrf().disable() //关闭CSRF（Cross-site request forgery）跨站请求伪造                .httpBasic().disable() //不支持HTTP Basic方式登录                .formLogin().disable()//不支持login页面登录                .cors() //开启跨域支持                .and()                //鉴权时只支持Bearer Token的形式，不支持url后加参数access_token                .oauth2ResourceServer()//开启oauth2资源认证                .jwt() //token为jwt                //默认情况下，权限是scope，而我们希望使用的是用户的角色，所以这里需要通过转换器进行处理                .jwtAuthenticationConverter(jwt -&gt; &#123; //通过自定义Converter来指定权限，Converter是函数接口，当前上下问参数为JWT对象                    Collection&lt;SimpleGrantedAuthority&gt; authorities =                            ((Collection&lt;String&gt;) jwt.getClaims()                                    .get(&quot;authorities&quot;)).stream() //获取JWT中的authorities                                    .map(SimpleGrantedAuthority::new)                                    .collect(Collectors.toSet());                    //如果希望保留scope的权限，可以取出scope数据然后合并到一起，这样因为不是以ROLE_开头，所以需要使用hasAuthority(&#x27;SCOPE_any&#x27;)的形式                    Collection&lt;SimpleGrantedAuthority&gt; scopes = ((Collection&lt;String&gt;) jwt.getClaims()                            .get(&quot;scope&quot;)).stream().map(scope -&gt; new SimpleGrantedAuthority(&quot;SCOPE_&quot; + scope))                            .collect(Collectors.toSet());                    //合并权限                    authorities.addAll(scopes);                    return Mono.just(new JwtAuthenticationToken(jwt, authorities));                &#125;)                .and()                .accessDeniedHandler(customServerAccessDeniedHandler)                .authenticationEntryPoint(customServerAuthenticationEntryPoint)                .and().build();    &#125;&#125;
CustomReactiveAuthorizationManager
基于RBAC权限认证管理模型的认证方式
package com.example.oauth2resourceserverwebfluxdemo.security;import org.springframework.http.server.reactive.ServerHttpRequest;import org.springframework.security.authorization.AuthorizationDecision;import org.springframework.security.authorization.ReactiveAuthorizationManager;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.web.server.authorization.AuthorizationContext;import org.springframework.stereotype.Component;import org.springframework.util.AntPathMatcher;import org.springframework.util.StringUtils;import reactor.core.publisher.Mono;import java.util.HashSet;import java.util.Set;/** * &lt;h1&gt;ReactiveAuthorizationManager&lt;/h1&gt; * Created by hanqf on 2020/11/30 12:05. */@Componentpublic class CustomReactiveAuthorizationManager implements ReactiveAuthorizationManager&lt;AuthorizationContext&gt; &#123;    @Override    public Mono&lt;AuthorizationDecision&gt; check(Mono&lt;Authentication&gt; authentication, AuthorizationContext object) &#123;        return authentication.map(auth -&gt; &#123;            ServerHttpRequest request = object.getExchange().getRequest();            Object principal = auth.getPrincipal();            String username;            if (principal instanceof Jwt) &#123;                username = ((Jwt) principal).getClaimAsString(&quot;user_name&quot;);            &#125; else &#123;                username = principal.toString();            &#125;            boolean hasPerssion = false;            if (StringUtils.hasText(username) &amp;&amp; !&quot;anonymousUser&quot;.equals(username)) &#123;                //根据用户名查询用户资源权限，这里应该访问数据库查询                Set&lt;String&gt; uris = new HashSet&lt;&gt;();                for (String uri : uris) &#123;                    //验证用户拥有的资源权限是否与请求的资源相匹配                    if (new AntPathMatcher().match(uri, request.getURI().toString())) &#123;                        hasPerssion = true;                        break;                    &#125;                &#125;            &#125;            //暂时全部返回true            hasPerssion = true;            return new AuthorizationDecision(hasPerssion);        &#125;);    &#125;&#125;
CustomServerAccessDeniedHandler
没有权限时的处理方式
package com.example.oauth2resourceserverwebfluxdemo.security;import com.example.oauth2resourceserverwebfluxdemo.exception.AjaxResponse;import com.example.oauth2resourceserverwebfluxdemo.exception.CustomException;import com.example.oauth2resourceserverwebfluxdemo.exception.CustomExceptionType;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import lombok.SneakyThrows;import org.springframework.http.MediaType;import org.springframework.http.server.reactive.ServerHttpResponse;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.web.server.authorization.ServerAccessDeniedHandler;import org.springframework.stereotype.Component;import org.springframework.web.server.ServerWebExchange;import reactor.core.publisher.Mono;/** * &lt;h1&gt;没有权限时的处理方式&lt;/h1&gt; * Created by hanqf on 2020/11/20 11:56. */@Componentpublic class CustomServerAccessDeniedHandler implements ServerAccessDeniedHandler &#123;    @SneakyThrows    @Override    public Mono&lt;Void&gt; handle(ServerWebExchange serverWebExchange, AccessDeniedException e) &#123;        return setErrorResponse(serverWebExchange.getResponse(),e.getMessage());    &#125;    protected Mono&lt;Void&gt; setErrorResponse(ServerHttpResponse response, String message) throws JsonProcessingException &#123;        response.getHeaders().setContentType(MediaType.APPLICATION_JSON);        ObjectMapper objectMapper = new ObjectMapper();        AjaxResponse ajaxResponse = AjaxResponse.error(new CustomException(CustomExceptionType.USER_INPUT_ERROR, message));        return response.writeWith(Mono.just(response.bufferFactory().wrap(objectMapper.writeValueAsBytes(ajaxResponse))));    &#125;&#125;
