token格式错误或过期时的处理方式
package com.example.oauth2resourceserverwebfluxdemo.security;import com.example.oauth2resourceserverwebfluxdemo.exception.AjaxResponse;import com.example.oauth2resourceserverwebfluxdemo.exception.CustomException;import com.example.oauth2resourceserverwebfluxdemo.exception.CustomExceptionType;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import lombok.SneakyThrows;import org.springframework.http.MediaType;import org.springframework.http.server.reactive.ServerHttpResponse;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.server.ServerAuthenticationEntryPoint;import org.springframework.stereotype.Component;import org.springframework.web.server.ServerWebExchange;import reactor.core.publisher.Mono;/** * &lt;h1&gt;ServerAuthenticationEntryPoint&lt;/h1&gt; * Created by hanqf on 2020/11/20 12:01. * &lt;p&gt; * token格式错误或过期时的处理方式 */@Componentpublic class CustomServerAuthenticationEntryPoint implements ServerAuthenticationEntryPoint &#123;    @SneakyThrows    @Override    public Mono&lt;Void&gt; commence(ServerWebExchange serverWebExchange, AuthenticationException e) &#123;        return setErrorResponse(serverWebExchange.getResponse(), e.getMessage());    &#125;    protected Mono&lt;Void&gt; setErrorResponse(ServerHttpResponse response, String message) throws JsonProcessingException &#123;        response.getHeaders().setContentType(MediaType.APPLICATION_JSON);        ObjectMapper objectMapper = new ObjectMapper();        AjaxResponse ajaxResponse = AjaxResponse.error(new CustomException(CustomExceptionType.USER_INPUT_ERROR, message));        return response.writeWith(Mono.just(response.bufferFactory().wrap(objectMapper.writeValueAsBytes(ajaxResponse))));    &#125;&#125;
