package com.example.oauth2resourceserverwebfluxdemo.config;import org.springframework.context.annotation.Configuration;import org.springframework.web.reactive.config.CorsRegistry;import org.springframework.web.reactive.config.WebFluxConfigurer;/** * &lt;h1&gt;WebFlux配置类&lt;/h1&gt; * Created by hanqf on 2020/11/18 17:43. * * 我们若需要配置Spring WebFlux只需让配置配实现接口WebFluxConfigurer， * 这样我们既能保留Spring Boot给WebFlux配置又能添加我们的定制配置。 * 若我们向完全控制WebFlux，则在配置类添加注解@EnableWebFlux * 配置方式和Spring MVC类似 */@Configurationpublic class WebFluxConfig implements WebFluxConfigurer &#123;    //跨域设置    @Override    public void addCorsMappings(CorsRegistry registry) &#123;        registry.addMapping(&quot;/**&quot;) //添加映射路径，“/**”表示对所有的路径实行全局跨域访问权限的设置                .allowedMethods(&quot;GET&quot;,&quot;POST&quot;, &quot;PUT&quot;, &quot;DELETE&quot;) //开放哪些Http方法，允许跨域访问                .allowedHeaders(&quot;*&quot;) //允许HTTP请求中的携带哪些Header信息                //When allowCredentials is true, allowedOrigins cannot contain the special value &quot;*&quot;since that cannot be set on the &quot;Access-Control-Allow-Origin&quot; response header.                // To allow credentials to a set of origins, list them explicitly or consider using &quot;allowedOriginPatterns&quot; instead.                //.allowedOrigins(&quot;*&quot;) //开放哪些ip、端口、域名的访问权限                .allowedOriginPatterns(&quot;*&quot;)                .allowCredentials(true); //是否允许发送Cookie信息    &#125;&#125;
