package com.example.oauth2resourceserverwebfluxdemo.controller;import com.example.oauth2resourceserverwebfluxdemo.exception.AjaxResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import reactor.core.publisher.Mono;import java.security.Principal;import java.util.HashMap;import java.util.Map;/** * &lt;h1&gt;res&lt;/h1&gt; * Created by hanqf on 2020/11/6 17:22. */@RestControllerpublic class UserController &#123;    //注意权限区分大小写    @PreAuthorize(&quot;hasRole(&#x27;admin&#x27;) or hasRole(&#x27;user&#x27;)&quot;)    //@PreAuthorize(&quot;#oauth2.hasScope(&#x27;any&#x27;)&quot;) //不支持oauth2表达式    @RequestMapping(value = &quot;/user&quot;)    public Mono&lt;AjaxResponse&gt; user(Principal principal) &#123;        //principal在经过security拦截后，是org.springframework.security.authentication.UsernamePasswordAuthenticationToken        //在经OAuth2拦截后，是OAuth2Authentication        return Mono.just(AjaxResponse.success(principal));    &#125;    //注意权限区分大小写    @PreAuthorize(&quot;hasAuthority(&#x27;SCOPE_any&#x27;)&quot;)    @RequestMapping(value = &quot;/user2&quot;)    public Mono&lt;AjaxResponse&gt; user2(Principal principal) &#123;        //principal在经过security拦截后，是org.springframework.security.authentication.UsernamePasswordAuthenticationToken        //在经OAuth2拦截后，是OAuth2Authentication        return Mono.just(AjaxResponse.success(principal));    &#125;    /**     * 获取用户的claim信息    */    @RequestMapping(&quot;/userInfo&quot;)    public Mono&lt;Map&lt;String, Object&gt;&gt; userInfo(Authentication authentication)&#123;        Map&lt;String,Object&gt; map = new HashMap&lt;&gt;();        Object principal = authentication.getPrincipal();        if(principal instanceof Jwt)&#123;            map.put(&quot;username&quot;, ((Jwt) principal).getClaim(&quot;user_name&quot;));            map.putAll(((Jwt) principal).getClaims());        &#125;        return Mono.just(map);    &#125;&#125;

摘要

通过本文，你将知道如何在WebFlux项目中通过redis注解缓存方法的返回值;
本项目基于springboot:2.4.0，jdk1.8，并使用Maven构建;
代码地址:https://github.com/hanqunfeng/reactive-redis-cache-annotation-spring-boot-starter


前言
最近在使用WebFlux时发现，SpringBoot提供的@Cacheable，@CachePut，@CacheEvict和@Caching注解不支持响应式方法，SpringBoot官方也没有提供响应式方法的缓存注解，看到网上的一些解决方案都是直接在方法代码中加入缓存数据的代码逻辑，这样虽然可以解决问题，但是代码侵入并不优雅，于是萌生自己写一个基于redis的响应式方法缓存注解的想法，本项目参考SpringBoot提供的@Cacheable，@CachePut，@CacheEvict和@Caching注解声明，但是只是实现了一些基本功能，可以满足绝大部分使用场景的要求，因为SpringBoot早晚会给出官方解决方案，在此之前，不妨一试。
