方法返回值必须是Mono或者Flux类型，使用方式与springboot提供的Cacheable等注解类似


/*** 缓存 cacheName和key支持EL表达式，实际key的名称是&quot;cacheName:key&quot;* 缓存结果* key:sys-user:find_lisi* value:* [* &quot;com.example.model.SysUser&quot;* &#123;*    id:&quot;5c74a4e4-c4f2-4570-8735-761d7a570d36&quot;*    username:&quot;lisi&quot;*    password:&quot;$2a$10$PXoGXLwg05.5YO.QtZa46ONypBmiK59yfefvO1OGO8kYFwzOB.Os6&quot;*    enable:true* &#125;* ]*/@ReactiveRedisCacheable(cacheName = &quot;sys-user&quot;, key = &quot;&#x27;find_&#x27; + #username&quot;)public Mono&lt;SysUser&gt; findUserByUsername(String username) &#123;    return sysUserRepository.findByUsername(username);&#125;@ReactiveRedisCacheable(cacheName = &quot;sys-user&quot;, key = &quot;all&quot;)public Flux&lt;SysUser&gt; findAll() &#123;    return sysUserRepository.findAll();&#125;/*** 删除缓存，allEntries = true 表示删除全部以&quot;cacheName:&quot;开头的缓存* allEntries 默认false，此时需要指定key的值，表示删除指定的&quot;cacheName:key&quot;*/@ReactiveRedisCacheEvict(cacheName = &quot;sys-user&quot;, allEntries = true)public Mono&lt;SysUser&gt; add(SysUser sysUser) &#123;    return sysUserRepository.addSysUser(sysUser.getId(), sysUser.getUsername(), sysUser.getPassword(), sysUser.getEnable()).flatMap(data -&gt; sysUserRepository.findById(sysUser.getId()));&#125;/*** 组合注解，用法与@Caching类似* 规则：* 1.cacheables不能与cacheEvicts或者cachePuts同时存在，因为后者一定会执行方法主体，达不到调用缓存的目的，所以当cacheables存在时，后者即便指定也不执行* 2.先执行cacheEvicts，再执行cachePuts*/@ReactiveRedisCaching(        evict = &#123;@ReactiveRedisCacheEvict(cacheName = &quot;sys-user&quot;, key = &quot;all&quot;)&#125;,        put = &#123;@ReactiveRedisCachePut(cacheName = &quot;sys-user&quot;, key = &quot;&#x27;find_&#x27; + #sysUser.username&quot;)&#125;)public Mono&lt;SysUser&gt; update(SysUser sysUser) &#123;    Mono&lt;SysUser&gt; save = sysUserRepository.save(sysUser);    return save;&#125;/*** 删除指定的&quot;cacheName:key&quot;*/@ReactiveRedisCacheEvict(cacheName = &quot;sys-user&quot;, key=&quot;&#x27;find_&#x27; + #username&quot;)public Mono&lt;Boolean&gt; deleteByUserName(String username) &#123;    return sysUserRepository.deleteByUsername(username);&#125;
RedisTemplate


如果使用时没有创建RedisTemplate，本项目中提供了一个默认的RedisTemplate，基于jackson序列化，支持jdk8的LocalDate和LocalDateTime


@Bean@ConditionalOnMissingBean(value = RedisTemplate.class)public RedisTemplate&lt;String, Object&gt; redisTemplate(RedisConnectionFactory redisConnectionFactory) &#123;    log.debug(&quot;ReactiveRedisConfig RedisTemplate&quot;);    ObjectMapper objectMapper = new ObjectMapper();    objectMapper.setVisibility(PropertyAccessor.ALL, JsonAutoDetect.Visibility.ANY);    //objectMapper.enableDefaultTyping(ObjectMapper.DefaultTyping.NON_FINAL);    objectMapper.activateDefaultTyping(objectMapper.getPolymorphicTypeValidator(), ObjectMapper.DefaultTyping.NON_FINAL, JsonTypeInfo.As.WRAPPER_ARRAY);    //LocalDateTime系列序列化和反序列化模块，继承自jsr310，我们在这里修改了日期格式    JavaTimeModule javaTimeModule = new JavaTimeModule();    //序列化    javaTimeModule.addSerializer(LocalDateTime.class, new LocalDateTimeSerializer(            DateTimeFormatter.ofPattern(DEFAULT_DATE_TIME_FORMAT)));    javaTimeModule.addSerializer(LocalDate.class,            new LocalDateSerializer(DateTimeFormatter.ofPattern(DEFAULT_DATE_FORMAT)));    javaTimeModule.addSerializer(LocalTime.class,            new LocalTimeSerializer(DateTimeFormatter.ofPattern(DEFAULT_TIME_FORMAT)));    //反序列化    javaTimeModule.addDeserializer(LocalDateTime.class, new LocalDateTimeDeserializer(            DateTimeFormatter.ofPattern(DEFAULT_DATE_TIME_FORMAT)));    javaTimeModule.addDeserializer(LocalDate.class,            new LocalDateDeserializer(DateTimeFormatter.ofPattern(DEFAULT_DATE_FORMAT)));    javaTimeModule.addDeserializer(LocalTime.class,            new LocalTimeDeserializer(DateTimeFormatter.ofPattern(DEFAULT_TIME_FORMAT)));    //注册模块    objectMapper.registerModule(javaTimeModule);    Jackson2JsonRedisSerializer&lt;Object&gt; serializer = new Jackson2JsonRedisSerializer&lt;&gt;(Object.class);    serializer.setObjectMapper(objectMapper);    RedisTemplate&lt;String, Object&gt; redisTemplate = new RedisTemplate&lt;&gt;();    redisTemplate.setConnectionFactory(redisConnectionFactory);    redisTemplate.setKeySerializer(new StringRedisSerializer());    redisTemplate.setValueSerializer(serializer);    redisTemplate.setHashKeySerializer(new StringRedisSerializer());    redisTemplate.setHashValueSerializer(serializer);    redisTemplate.afterPropertiesSet();    return redisTemplate;&#125;
