WebSecurityConfig


springboot没有为client-server设置独立的注解和配置类，而是把这部分功能整合到了spring-security中


package com.example.oauth2clientdemo2.config;import com.example.oauth2clientdemo2.exception.CustomException;import com.example.oauth2clientdemo2.security.CustomAccessDeniedHandler;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.web.client.RestTemplateCustomizer;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.http.HttpStatus;import org.springframework.http.client.ClientHttpRequestInterceptor;import org.springframework.http.client.ClientHttpResponse;import org.springframework.jdbc.core.JdbcOperations;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.builders.WebSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.client.JdbcOAuth2AuthorizedClientService;import org.springframework.security.oauth2.client.OAuth2AuthorizedClient;import org.springframework.security.oauth2.client.OAuth2AuthorizedClientService;import org.springframework.security.oauth2.client.authentication.OAuth2AuthenticationToken;import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;import org.springframework.util.CollectionUtils;import java.util.ArrayList;import java.util.List;/** * &lt;h1&gt;&lt;/h1&gt; * Created by hanqf on 2020/11/9 18:11. */@EnableWebSecurity@Configuration@Slf4jpublic class WebSecurityConfig extends WebSecurityConfigurerAdapter &#123;    @Value(&quot;$&#123;oauth2.server.logout&#125;&quot;)    private String oauth2_server_logout;    @Autowired    private CustomAccessDeniedHandler customAccessDeniedHandler;    /**     * 指定不拦截的路径规则     */    @Override    public void configure(WebSecurity web) throws Exception &#123;        //设置不需要拦截的路径，也就是不需要认证的路径        web.ignoring().antMatchers(&quot;/webjars/**&quot;);    &#125;    @Override    protected void configure(HttpSecurity http) throws Exception &#123;        //logout跳转到认证服务器的logout        http.logout().logoutSuccessUrl(oauth2_server_logout);        //配置认证规则        http.authorizeRequests()                .mvcMatchers(&quot;/oauth/login&quot;).permitAll()                ////所有路径都需要登录                .antMatchers(&quot;/&quot;).authenticated()                ////需要具备相应的角色才能访问，这里返回的权限是scope，所以还是使用rbac验证吧                .antMatchers(&quot;/user/**&quot;, &quot;/user2/**&quot;).hasAuthority(&quot;SCOPE_any&quot;)                .anyRequest().access(&quot;@rbacService.hasPerssion(request,authentication)&quot;);        //开启oauth2登录认证        http.oauth2Login();        //开启基于oauth2的客户端信息        http.oauth2Client();        http.csrf().disable();        http.exceptionHandling().accessDeniedHandler(customAccessDeniedHandler);    &#125;&#125;
