=code&amp;client_id=xxxxxxxxx&amp;scope=public_profile%20email&amp;state=BVZM3OW2EUS82pbjJdpQfXvtXbFbMwaUe_lRMOt4BW4%3D&amp;redirect_uri=http://localhost:8088/postman/login/oauth2/code/facebook          facebook: # facebook帐号登录，跳转到facebook登录页面            client-id: xxxxxxxxx #  客户端ID            client-secret: xxxxxxx #  客户端密码            client-name: Facebook认证          # /postman/oauth2/authorization/github          # 重定向后：https://github.com/login?client_id=xxxxxxxxx&amp;return_to=%2Flogin%2Foauth%2Fauthorize%3Fclient_id%3Dxxxxxxxxx%26redirect_uri%3Dhttp%253A%252F%252Flocalhost%253A8088%252Fpostman%252Flogin%252Foauth2%252Fcode%252Fgithub%26response_type%3Dcode%26scope%3Dread%253Auser%26state%3DmXtRWMQy8NaqVsFiie-NyYuy2z8OErrdq_VsuejDOPE%253D          # api文档：https://docs.github.com/cn/free-pro-team@latest/rest          github: # github帐号登录，跳转到github登录页面            client-id: xxxxxxxxx #  客户端ID            client-secret: xxxxxxx #  客户端密码            client-name: Github认证        provider:          my-client: # 6 注册客户端名称            authorization-uri: $&#123;oauth2.server.url&#125;/oauth/authorize # 7 认证地址            token-uri: $&#123;oauth2.server.url&#125;/oauth/token # 8 获取token地址            user-info-uri: http://localhost:8080/userInfo # 9 获取用户信息地址，必须配置            userNameAttribute: username # 10 指定用户信息中哪个属性是用户名称          my-client2: # 6 注册客户端名称            authorization-uri: $&#123;oauth2.server.url&#125;/oauth/authorize # 7 认证地址            token-uri: $&#123;oauth2.server.url&#125;/oauth/token # 8 获取token地址            user-info-uri: http://localhost:8080/userInfo # 9 获取用户信息地址，必须配置            userNameAttribute: username # 10 指定用户信息中哪个属性是用户名称
配置文件说明


springboot默认实现了google,facebook,github,okta的provider，但是其它认证服务器就需要自己指定provider信息。


这里需要为其指定user-info-uri，这个url提供认证用户的信息，需要认证服务端提供(也可以配置到受认证服务保护的资源服务中)，所以我们需要对认证服务进行改造


userNameAttribute表示从user-info-uri接口返回的信息中哪个属性名称表示用户名称


如果客户端信息只有一个，则访问当前客户端服务就会直接跳转到认证服务器的登录页面


如果客户端配置了多个，则会先跳转到login页面，需要选择要访问的认证服务器，后文有介绍如何自定义login页面


AuthServer改造
UserController
package com.example.oauth2authserverdemo.controller;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import java.util.HashMap;import java.util.Map;@RestControllerpublic class UserController &#123;    @RequestMapping(&quot;/userInfo&quot;)    public Map&lt;String, Object&gt; userInfo(Authentication authentication)&#123;        Map&lt;String,Object&gt; map = new HashMap&lt;&gt;();        Object principal = authentication.getPrincipal();        if(principal instanceof Jwt)&#123;            map.put(&quot;username&quot;, ((Jwt) principal).getClaim(&quot;user_name&quot;));            //客户端获取用户信息时，将附加信息一块返回给客户端            map.putAll(((Jwt) principal).getClaims());        &#125;        return map;    &#125;&#125;
UserController说明


这个接口就是普通的controller接口，其返回一个map信息，里面至少包含一个用户名称信息。


因为client-server与auth-server之间是通过基于JWT的access-token进行访问的，所以这个接口实际上也是一个资源接口，需要为认证服务器配置资源服务。


SecurityConfig
//认证服务器同时作为资源服务器，其目的是可以对外提供访问的资源，比如&quot;客户端认证获取用户信息&quot;//鉴权时只支持Bearer Token的形式，不支持url后加参数access_tokenhttp.oauth2ResourceServer().jwt() //开启oauth2资源认证        //默认情况下，权限是scope，而我们希望使用的是用户的角色，所以这里需要通过转换器进行处理        .jwtAuthenticationConverter(jwt -&gt; &#123; //通过自定义Converter来指定权限，Converter是函数接口，当前上下问参数为JWT对象            Collection&lt;SimpleGrantedAuthority&gt; authorities =                    ((Collection&lt;String&gt;) jwt.getClaims()                            .get(&quot;authorities&quot;)).stream() //获取JWT中的authorities                            .map(SimpleGrantedAuthority::new)                            .collect(Collectors.toSet());            //如果希望保留scope的权限，可以取出scope数据然后合并到一起，这样因为不是以ROLE_开头，所以需要使用hasAuthority(&#x27;SCOPE_any&#x27;)的形式            Collection&lt;SimpleGrantedAuthority&gt; scopes = ((Collection&lt;String&gt;) jwt.getClaims()                    .get(&quot;scope&quot;)).stream().map(scope -&gt; new SimpleGrantedAuthority(&quot;SCOPE_&quot; + scope))                    .collect(Collectors.toSet());            //合并权限            authorities.addAll(scopes);            return new JwtAuthenticationToken(jwt, authorities);        &#125;);
