package com.example.oauth2clientdemo2.controller;import lombok.extern.log4j.Log4j2;import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;import org.springframework.security.oauth2.client.registration.InMemoryClientRegistrationRepository;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.RequestMapping;import java.util.HashMap;import java.util.Map;/** * &lt;h1&gt;LoginController&lt;/h1&gt; * Created by hanqf on 2020/11/14 00:19. */@Controller@Log4j2public class LoginController &#123;    private final ClientRegistrationRepository clientRegistrationRepository;    public LoginController(ClientRegistrationRepository clientRegistrationRepository) &#123;        this.clientRegistrationRepository = clientRegistrationRepository;    &#125;    /**     * 自定义登录页面，多租户登录时先显示该页面，由用户选择要使用的认证服务     * @param model     * @return     */    @RequestMapping(&quot;/oauth/login&quot;)    public String login(Model model)&#123;        Map&lt;String,String&gt; map = new HashMap&lt;&gt;();        if(clientRegistrationRepository instanceof InMemoryClientRegistrationRepository)&#123;            ((InMemoryClientRegistrationRepository)clientRegistrationRepository).forEach(registrations-&gt;&#123;                String registrationId = registrations.getRegistrationId();                String clientName = registrations.getClientName();                map.put(registrationId,clientName);            &#125;);        &#125;        model.addAttribute(&quot;registrations&quot;, map);        return &quot;oauth2/login&quot;;    &#125;&#125;
