OAuth2AuthorizedClientService


默认每次客户端获取到的token信息都是存储在内存中的，如果服务器重启则token就会失效，可以将token保存到数据库中


创建数据表
# 客户端认证信息表，只需建表，数据会自动创建CREATE TABLE `oauth2_authorized_client` (    `client_registration_id` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT &#x27;客户端注册Id&#x27;,    `principal_name` varchar(200) COLLATE utf8mb4_bin NOT NULL COMMENT &#x27;登录用户名称&#x27;,    `access_token_type` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL COMMENT &#x27;验证类型，这里是bear&#x27;,    `access_token_value` blob DEFAULT NULL COMMENT &#x27;access_token的值&#x27;,    `access_token_issued_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT &#x27;access_token的创建时间&#x27;,    `access_token_expires_at` timestamp NOT NULL DEFAULT &#x27;0000-00-00 00:00:00&#x27; COMMENT &#x27;access_token的过期时间&#x27;,    `access_token_scopes` varchar(1000) COLLATE utf8mb4_bin DEFAULT NULL COMMENT &#x27;授权范围&#x27;,    `refresh_token_value` blob DEFAULT NULL COMMENT &#x27;refresh_token的值&#x27;,    `refresh_token_issued_at` timestamp NOT NULL DEFAULT &#x27;0000-00-00 00:00:00&#x27; COMMENT &#x27;refresh_token创建时间&#x27;,    `created_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT &#x27;数据创建时间&#x27;,    `update_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT &#x27;数据最后更新时间&#x27;,    PRIMARY KEY (`client_registration_id`,`principal_name`) USING BTREE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
