/*** 基于数据库的客户端信息配置，认证数据会自动创建到数据表中*/@Beanpublic OAuth2AuthorizedClientService authorizedClientService(JdbcOperations jdbcOperations, ClientRegistrationRepository clientRegistrationRepository) &#123;    JdbcOAuth2AuthorizedClientService authorizedClientService =            new JdbcOAuth2AuthorizedClientService(jdbcOperations, clientRegistrationRepository);    return authorizedClientService;&#125;@Autowiredprivate OAuth2AuthorizedClientService oAuth2AuthorizedClientService;//开启基于oauth2的客户端信息http.oauth2Client()        //客户端信息基于数据库，基于内存去掉下面配置即可        .authorizedClientService(oAuth2AuthorizedClientService);
访问资源服务


WebSecurityConfig配置类增加如下配置


其目的就是在使用RestTemplate访问资源服务时，在请求头中增加Bearer Token


/** * 调用Resource Server服务使用RestTemplate，当调用的Resource Server时候我们时需要使用Bearer Token在头部传递Access Token； * RestTemplateAutoConfiguration已经给我们自动配置了RestTemplateBuilder来配置RestTemplate，我们需要通过RestTemplateCustomizer来对RestTemplate来定制 */@BeanRestTemplateCustomizer restTemplateCustomizer(OAuth2AuthorizedClientService clientService) &#123;    return restTemplate -&gt; &#123; //1 RestTemplateCustomizer时函数接口，入参是RestTemplate        List&lt;ClientHttpRequestInterceptor&gt; interceptors = restTemplate.getInterceptors();        if (CollectionUtils.isEmpty(interceptors)) &#123;            interceptors = new ArrayList&lt;&gt;();        &#125;        interceptors.add((request, body, execution) -&gt; &#123; //2 通过增加RestTemplate拦截器，让每次请求添加Bearer Token（Access Token）；ClientHttpRequestInterceptor是函数接口，可用Lambda表达式来实现            OAuth2AuthenticationToken auth = (OAuth2AuthenticationToken)                    SecurityContextHolder.getContext().getAuthentication();            String clientRegistrationId = auth.getAuthorizedClientRegistrationId();            String principalName = auth.getName();            OAuth2AuthorizedClient client =                    clientService.loadAuthorizedClient(clientRegistrationId, principalName); //3 OAuth2AuthorizedClientService可获得用户的OAuth2AuthorizedClient            if (client == null) &#123;                //如果客户端信息使用的是基于内存的InMemoryOAuth2AuthorizedClientService，则重启服务器就会失效，需要重新登录才能恢复，                // 建议使用基于数据库的JdbcOAuth2AuthorizedClientService，本例使用的就是JdbcOAuth2AuthorizedClientService                throw new CustomException(HttpStatus.NOT_ACCEPTABLE, &quot;用户状态异常，请重新登录&quot;);            &#125;            String accessToken = client.getAccessToken().getTokenValue(); //4 OAuth2AuthorizedClient可获得用户Access Token            request.getHeaders().add(&quot;Authorization&quot;, &quot;Bearer &quot; + accessToken); //5 将Access Token通过头部的Bearer Token中访问Resource Server            log.info(String.format(&quot;请求地址: %s&quot;, request.getURI()));            log.info(String.format(&quot;请求头信息: %s&quot;, request.getHeaders()));            ClientHttpResponse response = execution.execute(request, body);            log.info(String.format(&quot;响应头信息: %s&quot;, response.getHeaders()));            return response;        &#125;);        restTemplate.setInterceptors(interceptors);    &#125;;&#125;
以ResController举例如何访问资源服务
package com.example.oauth2clientdemo2.controller;import com.example.oauth2clientdemo2.exception.AjaxResponse;import org.springframework.boot.web.client.RestTemplateBuilder;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.client.RestTemplate;import java.util.Map;/** * &lt;h1&gt;获取资源服务器数据&lt;/h1&gt; * Created by hanqf on 2020/11/7 22:47. */@RestController@RequestMapping(&quot;/res&quot;)public class ResController &#123;    private RestTemplate restTemplate;    public ResController(RestTemplateBuilder restTemplateBuilder) &#123;        this.restTemplate = restTemplateBuilder.build();    &#125;    /**     * 获取资源服务器的数据    */    @RequestMapping(&quot;/res1&quot;)    public AjaxResponse getRes()&#123;        return restTemplate.getForObject(&quot;http://localhost:8082/res/res1&quot;, AjaxResponse.class);    &#125;    @RequestMapping(&quot;/user&quot;)    public AjaxResponse getUser()&#123;        return restTemplate.postForObject(&quot;http://localhost:8082/user&quot;,null, AjaxResponse.class);    &#125;    @RequestMapping(&quot;/rbac&quot;)    public AjaxResponse getRbac()&#123;        return restTemplate.getForObject(&quot;http://localhost:8082/rbac&quot;, AjaxResponse.class);    &#125;    @RequestMapping(&quot;/userInfo&quot;)    public Map&lt;String, Object&gt; getuserInfo()&#123;        return restTemplate.getForObject(&quot;http://localhost:8082/userInfo&quot;, Map.class);    &#125;&#125;

