// 获取服务器完整地址var systemAddress = &quot;[[$&#123;#httpServletRequest.getScheme() + &#x27;://&#x27; + #httpServletRequest.getServerName() + &#x27;:&#x27; + #request.getServerPort()&#125;]]&quot;// 获取contextPathvar ctxPath  = &quot;[[@&#123;/&#125;]]&quot;;// 完整的请求路径前缀，注意后面跟的地址不要以`/`开头var serverPath = systemAddress + ctxPath;// 获取变量var modify = &quot;[[$&#123;modify&#125;]]&quot;;if(modify != &quot;add&quot;)&#123;    $(&quot;#password&quot;).attr(&quot;placeholder&quot;,&quot;[[#&#123;user.detail.changeNotice&#125;]]&quot;);&#125;


