spring.activemq.broker-url=tcp://localhost:61616spring.activemq.user=adminspring.activemq.password=admin#启用连接池spring.activemq.pool.enabled=true#最大连接数spring.activemq.pool.max-connections=100
配置类
@Configuration@EnableJms //启用jms功能public class ActiveMqConfig &#123;    //如果要使用topic类型的消息，则需要配置该bean    @Bean(&quot;jmsTopicListenerContainerFactory&quot;)    public JmsListenerContainerFactory jmsTopicListenerContainerFactory(            ConnectionFactory connectionFactory    )&#123;        DefaultJmsListenerContainerFactory factory                = new DefaultJmsListenerContainerFactory();        factory.setConnectionFactory(connectionFactory);        factory.setPubSubDomain(true); //这里必须设置为true，false则表示是queue类型        return factory;    &#125;    @Bean(&quot;springboot.queue&quot;)    public Queue queue() &#123;        return new ActiveMQQueue(&quot;springboot.queue&quot;) ;    &#125;    @Bean(&quot;springboot.topic&quot;)    public Topic topic() &#123;        return new ActiveMQTopic(&quot;springboot.topic&quot;) ;    &#125;    @Bean(&quot;springboot.queuereply&quot;)    public Queue queuereply() &#123;        return new ActiveMQQueue(&quot;springboot.queuereply&quot;) ;    &#125;&#125;
消费者
@Componentpublic class Consumer &#123;    //监听队列，queue类型    @JmsListener(destination=&quot;springboot.queue.a&quot;)    public void receiveQueueA(String text)&#123;        System.out.println(this.getClass().getName()+ &quot;收到的报文为:&quot;+text);    &#125;    @JmsListener(destination=&quot;springboot.*.b&quot;)    public void receiveQueueB(String text)&#123;        System.out.println(this.getClass().getName()+ &quot;收到的报文为:&quot;+text);    &#125;    @JmsListener(destination=&quot;springboot.&gt;&quot;)    public void receiveQueueAll(String text)&#123;        System.out.println(this.getClass().getName()+ &quot;收到的报文为:&quot;+text);    &#125;    //监听队列，topic类型，这里containerFactory要配置为jmsTopicListenerContainerFactory    @JmsListener(destination = &quot;springboot.topic&quot;,            containerFactory = &quot;jmsTopicListenerContainerFactory&quot;    )    public void receiveTopic(String text) &#123;        System.out.println(this.getClass().getName()+&quot; 收到的报文为:&quot;+text);    &#125;    @JmsListener(destination=&quot;springboot.queuereply&quot;)    @SendTo(&quot;out.replyTo.queue&quot;) //消费者应答后通知生产者    public String receiveQueueReply(String text)&#123;        System.out.println(this.getClass().getName()+ &quot;收到的报文为:&quot;+text);        return &quot;out.replyTo.queue receiveQueueReply&quot;;    &#125;&#125;
生产者
@Componentpublic class Producer &#123;    @Resource(&quot;springboot.queue.a&quot;)    private Queue queuea;    @Resource(&quot;springboot.queue.b&quot;)    private Queue queueb;    @Resource(&quot;springboot.topic&quot;)    private Topic topic;    @Resource(&quot;springboot.queuereply&quot;)    private Queue queuereply;    @Autowired    private JmsMessagingTemplate jmsTemplate;    // 发送消息，destination是发送到的队列，message是待发送的消息    public void sendMessage(Destination destination, final String message)&#123;        jmsTemplate.convertAndSend(destination, message);    &#125;    public void sendQueueAMessage(final String message)&#123;        sendMessage(queuea, message);    &#125;    public void sendQueueBMessage(final String message)&#123;        sendMessage(queueb, message);    &#125;    public void sendTopicMessage(final String message)&#123;        sendMessage(topic, message);    &#125;    public void sendQueueMessageReply(final String message)&#123;        sendMessage(queuereply, message);    &#125;    //生产者监听消费者的应答    @JmsListener(destination = &quot;out.replyTo.queue&quot;)    public void consumerMessage(String text)&#123;        System.out.println(&quot;从out.replyTo.queue收到报文&quot;+text);    &#125;&#125;

