这里用到一个工具类App\Helper\HttpUtils


namespace App\Helper;class HttpUtils&#123;    public static function request_by_curl($remote_server, $post_string) &#123;        $ch = curl_init();        curl_setopt($ch, CURLOPT_URL, $remote_server);        curl_setopt($ch, CURLOPT_POSTFIELDS, &#x27;data=&#x27; . $post_string);        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);        curl_setopt($ch, CURLOPT_USERAGENT, &#x27;Mozilla/5.0 (compatible; MSIE 5.01; Windows NT 5.0)&#x27;);        curl_setopt($ch, CURLOPT_TIMEOUT, 1);//异步处理        $data = curl_exec($ch);        if (curl_errno($ch)) &#123; //响应错误的处理        &#125;        curl_close($ch);        return $data;    &#125;&#125;

