Spring Boot项目中，Mybatis+通用Mapper+分页插件的配置方法



SpringBoot系列：Spring Boot学习笔记

前言
前文已经对Spring Boot中各种类型的数据访问做了说明，本文是对Spring Boot中使用Mybatis的扩展，重点说明如何在mybatis中集成通用Mapper和分页插件。
本文代码是在上文中讲到的mybatis单数据源配置的基础上进行扩展。
配置说明
pom中增加通用Mapper和分页插件的依赖：
&lt;!--分页插件--&gt;&lt;dependency&gt;    &lt;groupId&gt;com.github.pagehelper&lt;/groupId&gt;    &lt;artifactId&gt;pagehelper&lt;/artifactId&gt;    &lt;version&gt;4.2.1&lt;/version&gt;&lt;/dependency&gt;&lt;!--通用Mapper--&gt;&lt;dependency&gt;    &lt;groupId&gt;tk.mybatis&lt;/groupId&gt;    &lt;artifactId&gt;mapper&lt;/artifactId&gt;    &lt;version&gt;3.3.9&lt;/version&gt;&lt;/dependency&gt;
MyBatisConfig：在SqlSessionFactory中增加分页插件配置，因为通用Mapper是基于注解的，所以这里去掉xml的加载。
@Bean(name = &quot;sqlSessionFactory&quot;)public SqlSessionFactory sqlSessionFactoryBean() &#123;    SqlSessionFactoryBean bean = new SqlSessionFactoryBean();    bean.setDataSource(dataSource());    bean.setTypeAliasesPackage(&quot;com.example.pojo&quot;);    //分页插件设置    PageHelper pageHelper = new PageHelper();    Properties properties = new Properties();    properties.setProperty(&quot;reasonable&quot;, &quot;true&quot;);    properties.setProperty(&quot;supportMethodsArguments&quot;, &quot;true&quot;);    properties.setProperty(&quot;returnPageInfo&quot;, &quot;check&quot;);    properties.setProperty(&quot;params&quot;, &quot;count=countSql&quot;);    pageHelper.setProperties(properties);    //添加分页插件    bean.setPlugins(new Interceptor[]&#123;pageHelper&#125;);    ResourcePatternResolver resolver = new PathMatchingResourcePatternResolver();    try &#123;        //基于注解扫描Mapper，不需配置xml路径        //bean.setMapperLocations(resolver.getResources(&quot;classpath:mapper/*.xml&quot;));        return bean.getObject();    &#125; catch (Exception e) &#123;        e.printStackTrace();        throw new RuntimeException(e);    &#125;&#125;
MyBatisMapperScannerConfig
注意这里使用的是tk.mybatis.spring.mapper.MapperScannerConfigurer
package com.example;import org.springframework.boot.autoconfigure.AutoConfigureAfter;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import tk.mybatis.spring.mapper.MapperScannerConfigurer;import java.util.Properties;@Configuration//必须在MyBatisConfig注册后再加载MapperScannerConfigurer，否则会报错@AutoConfigureAfter(MyBatisConfig.class)public class MyBatisMapperScannerConfig &#123;    @Bean    public MapperScannerConfigurer mapperScannerConfigurer() &#123;        MapperScannerConfigurer mapperScannerConfigurer = new MapperScannerConfigurer();        mapperScannerConfigurer.setSqlSessionFactoryBeanName(&quot;sqlSessionFactory&quot;);        mapperScannerConfigurer.setBasePackage(&quot;com.example.mapper&quot;);        //初始化扫描器的相关配置，这里我们要创建一个Mapper的父类        Properties properties = new Properties();        properties.setProperty(&quot;mappers&quot;, &quot;com.example.MyMapper&quot;);        properties.setProperty(&quot;notEmpty&quot;, &quot;false&quot;);        properties.setProperty(&quot;IDENTITY&quot;, &quot;MYSQL&quot;);        mapperScannerConfigurer.setProperties(properties);        return mapperScannerConfigurer;    &#125;&#125;
MyMapper
package com.example;import tk.mybatis.mapper.common.Mapper;import tk.mybatis.mapper.common.MySqlMapper;public interface MyMapper&lt;T&gt; extends Mapper&lt;T&gt;, MySqlMapper&lt;T&gt; &#123;    //TODO    //FIXME 特别注意，该接口不能被扫描到，否则会出错&#125;
PersonMapper：实体mapper继承MyMapper即可，业务方法中我们就可以使用通用Mapper提供的各种方法
package com.example.mapper;import com.example.MyMapper;import com.example.pojo.Person;public interface PersonMapper extends MyMapper&lt;Person&gt; &#123;    //以下方法用于演示，当通用Mapper不能买足需求时，可以自己扩展相应的方法    //不允许查询参数为空的情况    @Select(&#123;            &quot;select&quot;,            &quot;p_id, p_name, p_age&quot;,            &quot;from person&quot;,            &quot;where  p_age between #&#123;startAge&#125; and #&#123;endAge&#125;&quot;    &#125;)    @Results(&#123;            @Result(column=&quot;p_id&quot;, property=&quot;pId&quot;, jdbcType= JdbcType.INTEGER, id=true),            @Result(column=&quot;p_name&quot;, property=&quot;pName&quot;, jdbcType=JdbcType.VARCHAR),            @Result(column=&quot;p_age&quot;, property=&quot;pAge&quot;, jdbcType=JdbcType.INTEGER)    &#125;)    List&lt;Person&gt; queryListByParam(Person person);    //允许查询参数为空的情况    @SelectProvider(type = PersonSqlProvider.class,method = &quot;selectSelective&quot;)    @Results(&#123;            @Result(column=&quot;p_id&quot;, property=&quot;pId&quot;, jdbcType= JdbcType.INTEGER, id=true),            @Result(column=&quot;p_name&quot;, property=&quot;pName&quot;, jdbcType=JdbcType.VARCHAR),            @Result(column=&quot;p_age&quot;, property=&quot;pAge&quot;, jdbcType=JdbcType.INTEGER)    &#125;)    List&lt;Person&gt; queryListByParamSelective(Person person);&#125;
package com.example.mapper;import com.example.pojo.Person;import static org.apache.ibatis.jdbc.SqlBuilder.*;public class PersonSqlProvider &#123;    public String selectSelective(Person record)&#123;        BEGIN();        SELECT(&quot;p_id, p_name, p_age&quot;);        FROM(&quot;person&quot;);        WHERE(&quot;1=1&quot;);        if(record.getStartAge()!=null)&#123;            AND();            WHERE(&quot;p_age &gt;= #&#123;startAge&#125;&quot;);        &#125;        if(record.getEndAge()!=null)&#123;            AND();            WHERE(&quot;p_age &lt;= #&#123;endAge&#125;&quot;);        &#125;        return SQL();    &#125;&#125;
这里要注意，使用通用Mapper时，实体类必须有一个叫做id的整型主键，另外，为了方便使用分页插件，要在每个实体对象中定义两个属性–page和rows，我们可以把这些通用的属性放到父类中，比如我们创建一个父类：BaseEntity
BaseEntity
package com.example.pojo;import javax.persistence.Transient;public class BaseEntity &#123;    @Id    //注意，如果是老的项目，表中的主键可能不叫做id，这时可以在父类中去掉这个属性，改在子类中实现    @Column(name = &quot;id&quot;)    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Integer id;    @Transient    private Integer page = 1;    @Transient    private Integer rows = 10;&#125;
