Spring Boot的事务管理
JDBC事务管理
如果我们项目中使用的是JDBC的数据访问方案，并且容器中只注册了一个DataSource，那么SpringBoot就会为我们开启DataSourceTransactionManagerAutoConfiguration的自动配置类，其会在容器中注册一个DataSourceTransactionManager事务管理器，同时会开启对注解式事务**@Transactional的支持。感兴趣的可以看一下DataSourceTransactionManagerAutoConfiguration**的源码。

@Transactional是Spring框架提供的，配置方法参考下面的代码
//一般我们会在业务实现类上声明事务注解//当前表示需要在事务中运行，可以执行更新和删除操作，遇到异常则回滚@Transactional(propagation = Propagation.REQUIRED, readOnly = false, rollbackFor = &#123; Exception.class &#125;)public class PersonService&#123;    //方法上也可以标注事务注解，方法上注解声明会覆盖类上的    //一般查询操作readOnly设置为true，增删该操作设置为false    @Transactional(readOnly = true)    public List&lt;Person&gt; getAllPersonList()&#123;        //do something    &#125;    //不加@Transactiona注解，则使用类上的设置    public int savePserson(Person person)&#123;        //do something    &#125;&#125;
如果在测试类上声明**@Transactional**，则会开启自动回滚，不会产生脏数据
@RunWith(SpringRunner.class)@SpringBootTest@Transactionalpublic class SpringbootjdbcdemoApplicationTests &#123;…………&#125;

如果希望自己配置事务，可以在配置类中增加事务管理器的配置，比如，我们在DataSourceConfig中增加如下配置：
@Configuration//启用注解事务管理，使用CGLib代理@EnableTransactionManagement(proxyTargetClass = true)public class DataSourceConfig &#123;    @Value(&quot;$&#123;spring.datasource.driver-class-name&#125;&quot;)    String driverClass;    @Value(&quot;$&#123;spring.datasource.url&#125;&quot;)    String url;    @Value(&quot;$&#123;spring.datasource.username&#125;&quot;)    String userName;    @Value(&quot;$&#123;spring.datasource.password&#125;&quot;)    String passWord;    @Bean(name = &quot;dataSource&quot;)    public DataSource dataSource() &#123;        DriverManagerDataSource dataSource = new DriverManagerDataSource();        dataSource.setDriverClassName(driverClass);        dataSource.setUrl(url);        dataSource.setUsername(userName);        dataSource.setPassword(passWord);        return dataSource;    &#125;    @Bean(name = &quot;jdbcTemplate&quot;)    public JdbcTemplate jdbcTemplate()&#123;        JdbcTemplate jdbcTemplate = new JdbcTemplate(dataSource());        return jdbcTemplate;    &#125;    @Bean    public DataSourceTransactionManager transactionManager() &#123;        return new DataSourceTransactionManager(dataSource());    &#125;&#125;

说明
上面的方法只是针对单一数据源进行事务管理的，但是项目中经常会用到多数据源的情况，那么要如何进行事务管理呢？

我们上文讲到了可以在项目中通过配置类，自己配置多个数据源，并通过DataSourceConfig进行了演示，接下来我们添加多个事务管理器。
@Configuration//启用注解事务管理，使用CGLib代理@EnableTransactionManagement(proxyTargetClass = true)public class DataSourceConfig &#123;    @Value(&quot;$&#123;spring.datasource.driver-class-name&#125;&quot;)    String driverClass;    @Value(&quot;$&#123;spring.datasource.url&#125;&quot;)    String url;    @Value(&quot;$&#123;spring.datasource.username&#125;&quot;)    String userName;    @Value(&quot;$&#123;spring.datasource.password&#125;&quot;)    String passWord;    @Value(&quot;$&#123;spring.datasource.driver-class-name2&#125;&quot;)    String driverClass2;    @Value(&quot;$&#123;spring.datasource.url2&#125;&quot;)    String url2;    @Value(&quot;$&#123;spring.datasource.username2&#125;&quot;)    String userName2;    @Value(&quot;$&#123;spring.datasource.password2&#125;&quot;)    String passWord2;    @Bean(name = &quot;dataSource&quot;)    public DataSource dataSource() &#123;        DriverManagerDataSource dataSource = new DriverManagerDataSource();        dataSource.setDriverClassName(driverClass);        dataSource.setUrl(url);        dataSource.setUsername(userName);        dataSource.setPassword(passWord);        return dataSource;    &#125;    @Bean(name = &quot;jdbcTemplate&quot;)    public JdbcTemplate jdbcTemplate()&#123;        JdbcTemplate jdbcTemplate = new JdbcTemplate(dataSource());        return jdbcTemplate;    &#125;    @Bean(name = &quot;transactionManager&quot;)    public DataSourceTransactionManager transactionManager() &#123;        return new DataSourceTransactionManager(dataSource());    &#125;    @Bean(name = &quot;dataSource2&quot;)    public DataSource dataSource2() &#123;        DriverManagerDataSource dataSource = new DriverManagerDataSource();        dataSource.setDriverClassName(driverClass2);        dataSource.setUrl(url2);        dataSource.setUsername(userName2);        dataSource.setPassword(passWord2);        System.out.println(url2);        return dataSource;    &#125;    @Bean(name = &quot;jdbcTemplate2&quot;)    public JdbcTemplate jdbcTemplate2()&#123;        JdbcTemplate jdbcTemplate = new JdbcTemplate(dataSource2());        return jdbcTemplate;    &#125;    @Bean(name = &quot;transactionManager2&quot;)    public DataSourceTransactionManager transactionManager2() &#123;        return new DataSourceTransactionManager(dataSource2());    &#125;&#125;
这时，我们必须在**@Transactional**注解中指定要使用哪一个事务管理器
@Service@Transactional(transactionManager = &quot;transactionManager&quot;,propagation = Propagation.REQUIRED, readOnly = false, rollbackFor = &#123; Exception.class &#125;)public class PersonService &#123;    @Autowired    private PersonDao personDao;    public int savePserson(Person person)&#123;        return personDao.savePerson(person);    &#125;    @Transactional(transactionManager = &quot;transactionManager&quot;,readOnly = true)    public List&lt;Person&gt; getAllPersonList()&#123;        return personDao.getAllPersonList();    &#125;    @Transactional(transactionManager = &quot;transactionManager2&quot;,propagation = Propagation.REQUIRED, readOnly = false, rollbackFor = &#123; Exception.class &#125;)    public int savePserson2(Person person)&#123;        return personDao.savePerson2(person);    &#125;    @Transactional(transactionManager = &quot;transactionManager2&quot;,readOnly = true)    public List&lt;Person&gt; getAllPersonList2()&#123;        return personDao.getAllPersonList2();    &#125;&#125;

说明
这样做并不美好，不能对多个数据源同时进行事务管理，比如，我们在一个业务方法里同时对两个数据源进行操作，我们希望只要有一个发生异常，则两个数据源的数据都进行回滚。
那要怎么做呢，我们接着往下看。

多数据源事务管理
这里推荐使用**Atomikos**，Atomikos支持Mysql、Oracle等多种数据库，可与多种ORM框架集成，如MyBatis、JPA、Hibernate等等，同时支持各种容器下JNDI的多数据源管理。Atomikos官网提供了各种情况下使用Atomikos的Example，本文只对使用JDBC时的情况进行说明。
目前maven中央仓库的最新版本是4.0.4，使用Atomikos，需要在项目中加入如下依赖：
&lt;dependency&gt;    &lt;groupId&gt;com.atomikos&lt;/groupId&gt;    &lt;artifactId&gt;transactions-jdbc&lt;/artifactId&gt;    &lt;version&gt;4.0.4&lt;/version&gt;&lt;/dependency&gt;&lt;dependency&gt;    &lt;groupId&gt;com.atomikos&lt;/groupId&gt;    &lt;artifactId&gt;transactions-jta&lt;/artifactId&gt;    &lt;version&gt;4.0.4&lt;/version&gt;&lt;/dependency&gt;&lt;dependency&gt;    &lt;groupId&gt;com.atomikos&lt;/groupId&gt;    &lt;artifactId&gt;transactions&lt;/artifactId&gt;    &lt;version&gt;4.0.4&lt;/version&gt;&lt;/dependency&gt;&lt;dependency&gt;    &lt;groupId&gt;com.atomikos&lt;/groupId&gt;    &lt;artifactId&gt;atomikos-util&lt;/artifactId&gt;    &lt;version&gt;4.0.4&lt;/version&gt;&lt;/dependency&gt; &lt;dependency&gt;    &lt;groupId&gt;javax.transaction&lt;/groupId&gt;    &lt;artifactId&gt;jta&lt;/artifactId&gt;    &lt;version&gt;1.1&lt;/version&gt;&lt;/dependency&gt;
对DataSourceConfig进行改造：
package com.example;import com.atomikos.icatch.jta.UserTransactionImp;import com.atomikos.icatch.jta.UserTransactionManager;import com.atomikos.jdbc.AtomikosDataSourceBean;import com.mysql.jdbc.jdbc2.optional.MysqlXADataSource;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.DependsOn;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.annotation.EnableTransactionManagement;import org.springframework.transaction.jta.JtaTransactionManager;import javax.sql.DataSource;import javax.transaction.TransactionManager;import javax.transaction.UserTransaction;@Configuration//启用注解事务管理，使用CGLib代理@EnableTransactionManagement(proxyTargetClass = true)public class DataSourceConfig &#123;    @Value(&quot;$&#123;spring.datasource.driver-class-name&#125;&quot;)    String driverClass;    @Value(&quot;$&#123;spring.datasource.url&#125;&quot;)    String url;    @Value(&quot;$&#123;spring.datasource.username&#125;&quot;)    String userName;    @Value(&quot;$&#123;spring.datasource.password&#125;&quot;)    String passWord;    @Value(&quot;$&#123;spring.datasource.driver-class-name2&#125;&quot;)    String driverClass2;    @Value(&quot;$&#123;spring.datasource.url2&#125;&quot;)    String url2;    @Value(&quot;$&#123;spring.datasource.username2&#125;&quot;)    String userName2;    @Value(&quot;$&#123;spring.datasource.password2&#125;&quot;)    String passWord2;    @Bean(name = &quot;userTransaction&quot;)    public UserTransaction userTransaction() throws Throwable &#123;        UserTransactionImp userTransactionImp = new UserTransactionImp();        userTransactionImp.setTransactionTimeout(300);        return userTransactionImp;    &#125;    @Bean(name = &quot;atomikosTransactionManager&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public TransactionManager atomikosTransactionManager() throws Throwable &#123;        UserTransactionManager userTransactionManager = new UserTransactionManager();        userTransactionManager.setForceShutdown(true);        return userTransactionManager;    &#125;    @Bean(name = &quot;transactionManager&quot;)    @DependsOn(&#123; &quot;userTransaction&quot;, &quot;atomikosTransactionManager&quot; &#125;)    public PlatformTransactionManager transactionManager() throws Throwable &#123;        UserTransaction userTransaction = userTransaction();        TransactionManager atomikosTransactionManager = atomikosTransactionManager();        JtaTransactionManager jtaTransactionManager = new JtaTransactionManager(userTransaction, atomikosTransactionManager);        jtaTransactionManager.setAllowCustomIsolationLevels(true);        return jtaTransactionManager;    &#125;    @Bean(name = &quot;dataSource&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public DataSource dataSource() &#123;        System.out.println(&quot;dataSource init&quot;);        //Oracle:oracle.jdbc.xa.client.OracleXADataSource        //Druid:com.alibaba.druid.pool.xa.DruidXADataSource        //Postgresql:org.postgresql.xa.PGXADataSource        MysqlXADataSource mysqlXaDataSource = new MysqlXADataSource();        mysqlXaDataSource.setUrl(url);        mysqlXaDataSource.setPassword(passWord);        mysqlXaDataSource.setUser(userName);        mysqlXaDataSource.setPinGlobalTxToPhysicalConnection(true);        AtomikosDataSourceBean xaDataSource = new AtomikosDataSourceBean();        xaDataSource.setXaDataSource(mysqlXaDataSource);        xaDataSource.setUniqueResourceName(&quot;dataSource&quot;);        xaDataSource.setMinPoolSize(10);        xaDataSource.setPoolSize(10);        xaDataSource.setMaxPoolSize(30);        xaDataSource.setBorrowConnectionTimeout(60);        xaDataSource.setReapTimeout(20);        xaDataSource.setMaxIdleTime(60);        xaDataSource.setMaintenanceInterval(60);        return xaDataSource;    &#125;    @Bean(name = &quot;dataSource2&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public DataSource dataSource2() &#123;        System.out.println(&quot;dataSource2 init&quot;);        MysqlXADataSource mysqlXaDataSource = new MysqlXADataSource();        mysqlXaDataSource.setUrl(url2);        mysqlXaDataSource.setPassword(passWord2);        mysqlXaDataSource.setUser(userName2);        mysqlXaDataSource.setPinGlobalTxToPhysicalConnection(true);        AtomikosDataSourceBean xaDataSource = new AtomikosDataSourceBean();        xaDataSource.setXaDataSource(mysqlXaDataSource);        xaDataSource.setUniqueResourceName(&quot;dataSource2&quot;);        xaDataSource.setMinPoolSize(10);        xaDataSource.setPoolSize(10);        xaDataSource.setMaxPoolSize(30);        xaDataSource.setBorrowConnectionTimeout(60);        xaDataSource.setReapTimeout(20);        xaDataSource.setMaxIdleTime(60);        xaDataSource.setMaintenanceInterval(60);        return xaDataSource;    &#125;    @Bean(name = &quot;jdbcTemplate&quot;)    public JdbcTemplate jdbcTemplate()&#123;        JdbcTemplate jdbcTemplate = new JdbcTemplate(dataSource());        return jdbcTemplate;    &#125;    @Bean(name = &quot;jdbcTemplate2&quot;)    public JdbcTemplate jdbcTemplate2()&#123;        JdbcTemplate jdbcTemplate = new JdbcTemplate(dataSource2());        return jdbcTemplate;    &#125;&#125;
