package com.example;import com.atomikos.icatch.jta.UserTransactionImp;import com.atomikos.icatch.jta.UserTransactionManager;import com.atomikos.jdbc.AtomikosDataSourceBean;import com.example.hibernate.CP_HibernateDAO;import com.example.hibernate.impl.CP_Hibernate4DAOImpl;import com.mysql.jdbc.jdbc2.optional.MysqlXADataSource;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.DependsOn;import org.springframework.orm.hibernate4.LocalSessionFactoryBean;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.annotation.EnableTransactionManagement;import org.springframework.transaction.jta.JtaTransactionManager;import javax.sql.DataSource;import javax.transaction.TransactionManager;import javax.transaction.UserTransaction;import java.util.Properties;@Configuration@EnableTransactionManagement(proxyTargetClass = true)public class DataSourceConfig &#123;    @Value(&quot;$&#123;spring.datasource.driver-class-name&#125;&quot;)    String driverClass;    @Value(&quot;$&#123;spring.datasource.url&#125;&quot;)    String url;    @Value(&quot;$&#123;spring.datasource.username&#125;&quot;)    String userName;    @Value(&quot;$&#123;spring.datasource.password&#125;&quot;)    String passWord;    @Value(&quot;$&#123;spring.datasource.driver-class-name2&#125;&quot;)    String driverClass2;    @Value(&quot;$&#123;spring.datasource.url2&#125;&quot;)    String url2;    @Value(&quot;$&#123;spring.datasource.username2&#125;&quot;)    String userName2;    @Value(&quot;$&#123;spring.datasource.password2&#125;&quot;)    String passWord2;    @Bean(name = &quot;userTransaction&quot;)    public UserTransaction userTransaction() throws Throwable &#123;        UserTransactionImp userTransactionImp = new UserTransactionImp();        userTransactionImp.setTransactionTimeout(10000);        return userTransactionImp;    &#125;    @Bean(name = &quot;atomikosTransactionManager&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public TransactionManager atomikosTransactionManager() throws Throwable &#123;        UserTransactionManager userTransactionManager = new UserTransactionManager();        userTransactionManager.setForceShutdown(true);        return userTransactionManager;    &#125;    @Bean(name = &quot;transactionManager&quot;)    @DependsOn(&#123; &quot;userTransaction&quot;, &quot;atomikosTransactionManager&quot; &#125;)    public PlatformTransactionManager transactionManager() throws Throwable &#123;        System.out.println();        UserTransaction userTransaction = userTransaction();        TransactionManager atomikosTransactionManager = atomikosTransactionManager();        JtaTransactionManager jtaTransactionManager = new JtaTransactionManager(userTransaction, atomikosTransactionManager);        jtaTransactionManager.setAllowCustomIsolationLevels(true);        return jtaTransactionManager;    &#125;    @Bean(name = &quot;dataSource&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public DataSource dataSource() &#123;        System.out.println();        MysqlXADataSource mysqlXaDataSource = new MysqlXADataSource();        mysqlXaDataSource.setUrl(url);        mysqlXaDataSource.setPassword(passWord);        mysqlXaDataSource.setUser(userName);        mysqlXaDataSource.setPinGlobalTxToPhysicalConnection(true);        AtomikosDataSourceBean xaDataSource = new AtomikosDataSourceBean();        xaDataSource.setXaDataSource(mysqlXaDataSource);        xaDataSource.setUniqueResourceName(&quot;dataSource&quot;);        xaDataSource.setMinPoolSize(10);        xaDataSource.setPoolSize(10);        xaDataSource.setMaxPoolSize(30);        xaDataSource.setBorrowConnectionTimeout(60);        xaDataSource.setReapTimeout(20);        xaDataSource.setMaxIdleTime(60);        xaDataSource.setMaintenanceInterval(60);        return xaDataSource;    &#125;    @Bean(name = &quot;dataSource2&quot;, initMethod = &quot;init&quot;, destroyMethod = &quot;close&quot;)    public DataSource dataSource2() &#123;        System.out.println();        MysqlXADataSource mysqlXaDataSource = new MysqlXADataSource();        mysqlXaDataSource.setUrl(url2);        mysqlXaDataSource.setPassword(passWord2);        mysqlXaDataSource.setUser(userName2);        mysqlXaDataSource.setPinGlobalTxToPhysicalConnection(true);        AtomikosDataSourceBean xaDataSource = new AtomikosDataSourceBean();        xaDataSource.setXaDataSource(mysqlXaDataSource);        xaDataSource.setUniqueResourceName(&quot;dataSource2&quot;);        xaDataSource.setMinPoolSize(10);        xaDataSource.setPoolSize(10);        xaDataSource.setMaxPoolSize(30);        xaDataSource.setBorrowConnectionTimeout(60);        xaDataSource.setReapTimeout(20);        xaDataSource.setMaxIdleTime(60);        xaDataSource.setMaintenanceInterval(60);        return xaDataSource;    &#125;    @Bean(name = &quot;sessionFactory&quot;)    public LocalSessionFactoryBean localSessionFactoryBean() &#123;        System.out.println(&quot;sessionFactory&quot;);        LocalSessionFactoryBean sessionFactory = new LocalSessionFactoryBean();        sessionFactory.setDataSource(dataSource());        //扫描实体对象的目录，不同的数据源，实体要存放不同的目录        String[] packagesToScan = new String[] &#123; &quot;com.example.model.ds1&quot; &#125;;        sessionFactory.setPackagesToScan(packagesToScan);        Properties hibernateProperties = new Properties();        hibernateProperties.setProperty(&quot;hibernate.dialect&quot;, &quot;org.hibernate.dialect.MySQLDialect&quot;);        hibernateProperties.setProperty(&quot;hibernate.show_sql&quot;, &quot;true&quot;);        //开启Hibernate对JTA的支持        hibernateProperties.setProperty(&quot;hibernate.current_session_context_class&quot;, &quot;jta&quot;);        hibernateProperties.setProperty(&quot;hibernate.transaction.factory_class&quot;, &quot;org.hibernate.transaction.JTATransactionFactory&quot;);        sessionFactory.setHibernateProperties(hibernateProperties);        return sessionFactory;    &#125;    @Bean(name = &quot;sessionFactory2&quot;)    public LocalSessionFactoryBean localSessionFactoryBean2() &#123;        System.out.println(&quot;sessionFactory2&quot;);        LocalSessionFactoryBean sessionFactory = new LocalSessionFactoryBean();        sessionFactory.setDataSource(dataSource2());        //扫描实体对象的目录，不同的数据源，实体要存放不同的目录        String[] packagesToScan = new String[] &#123; &quot;com.example.model.ds2&quot; &#125;;        sessionFactory.setPackagesToScan(packagesToScan);        Properties hibernateProperties = new Properties();        hibernateProperties.setProperty(&quot;hibernate.dialect&quot;, &quot;org.hibernate.dialect.MySQLDialect&quot;);        hibernateProperties.setProperty(&quot;hibernate.show_sql&quot;, &quot;true&quot;);        //开启Hibernate对JTA的支持        hibernateProperties.setProperty(&quot;hibernate.current_session_context_class&quot;, &quot;jta&quot;);        hibernateProperties.setProperty(&quot;hibernate.transaction.factory_class&quot;, &quot;org.hibernate.transaction.JTATransactionFactory&quot;);        sessionFactory.setHibernateProperties(hibernateProperties);        return sessionFactory;    &#125;    @Bean(name = &quot;hibernateDAO&quot;)    public CP_HibernateDAO hibernate4Dao() &#123;        System.out.println(&quot;hibernateDAO&quot;);        CP_Hibernate4DAOImpl dao = new CP_Hibernate4DAOImpl();        //绑定SessionFactory        dao.setSessionFactory(localSessionFactoryBean().getObject());        return dao;    &#125;    @Bean(name = &quot;hibernateDAO2&quot;)    public CP_HibernateDAO hibernate4Dao2() &#123;        System.out.println(&quot;hibernateDAO2&quot;);        CP_Hibernate4DAOImpl dao = new CP_Hibernate4DAOImpl();        //绑定SessionFactory2        dao.setSessionFactory(localSessionFactoryBean2().getObject());        return dao;    &#125;&#125;
