CP_HibernateDAO是我们自定义的Hibernate的通用Dao接口，其定义的方法和和实现类CP_Hibernate4DAOImpl代码如下：
package com.example.hibernate;import java.util.List;public interface CP_HibernateDAO &#123;    public List&lt;?&gt; findAll(Class&lt;?&gt; entityClazz, String... str);    public void save(Object entity);&#125;
package com.example.hibernate.impl;import com.example.hibernate.CP_HibernateDAO;import org.hibernate.Criteria;import org.hibernate.Session;import org.hibernate.SessionFactory;import org.hibernate.criterion.DetachedCriteria;import java.util.List;public class CP_Hibernate4DAOImpl implements CP_HibernateDAO &#123;    private SessionFactory sessionFactory;    public SessionFactory getSessionFactory() &#123;        return sessionFactory;    &#125;    //绑定SessionFactory    public void setSessionFactory(SessionFactory sessionFactory) &#123;        this.sessionFactory = sessionFactory;    &#125;    private Session getHibernateSession() &#123;        Session session = sessionFactory.openSession();        return session;    &#125;    /*     * @see com.example.hibernate.CP_HibernateDAO#findAll()     */    @Override    public List&lt;?&gt; findAll(Class&lt;?&gt; entityClazz, String... str) &#123;        DetachedCriteria dc = DetachedCriteria.forClass(entityClazz);        List&lt;?&gt; list = findAllByCriteria(dc);        return list;    &#125;    /*     * @see com.example.hibernate.CP_HibernateDAO#save(java.lang.Object)     */    @Override    public void save(Object entity) &#123;        getHibernateSession().save(entity);        //注意这里一定要执行flush方法        getHibernateSession().flush();    &#125;    public List&lt;?&gt; findAllByCriteria(DetachedCriteria detachedCriteria) &#123;        // TODO Auto-generated method stub        Criteria criteria = detachedCriteria                .getExecutableCriteria(getHibernateSession());        return criteria.list();    &#125;&#125;

说明
需要注意两点：


session必须使用sessionFactory.openSession()的方式获得，不能使用sessionFactory.getCurrentSession()。


更新操作必须调用session.flush()方法。


Spring配置文件的方式，可以参考：Spring4+Hibernate4+Atomikos3.3多数据源事务管理

