创建MyBatisConfig
@Configuration@EnableTransactionManagement(proxyTargetClass = true)public class MyBatisConfig &#123;    @Value(&quot;$&#123;spring.datasource.driver-class-name&#125;&quot;)    String driverClass;    @Value(&quot;$&#123;spring.datasource.url&#125;&quot;)    String url;    @Value(&quot;$&#123;spring.datasource.username&#125;&quot;)    String userName;    @Value(&quot;$&#123;spring.datasource.password&#125;&quot;)    String passWord;    @Bean(name = &quot;dataSource&quot;)    public DataSource dataSource() &#123;        DriverManagerDataSource dataSource = new DriverManagerDataSource();        dataSource.setDriverClassName(driverClass);        dataSource.setUrl(url);        dataSource.setUsername(userName);        dataSource.setPassword(passWord);        return dataSource;    &#125;    @Bean(name = &quot;sqlSessionFactory&quot;)    public SqlSessionFactory sqlSessionFactoryBean() &#123;        SqlSessionFactoryBean bean = new SqlSessionFactoryBean();        bean.setDataSource(dataSource());        //添加XML目录        ResourcePatternResolver resolver = new PathMatchingResourcePatternResolver();        try &#123;            bean.setMapperLocations(resolver.getResources(&quot;classpath:mapper/*.xml&quot;));            return bean.getObject();        &#125; catch (Exception e) &#123;            e.printStackTrace();            throw new RuntimeException(e);        &#125;    &#125;    @Bean    public SqlSessionTemplate sqlSessionTemplate(SqlSessionFactory sqlSessionFactory) &#123;        return new SqlSessionTemplate(sqlSessionFactory);    &#125;    @Bean    public PlatformTransactionManager annotationDrivenTransactionManager() &#123;        return new DataSourceTransactionManager(dataSource());    &#125;&#125;
MyBatisMapperScannerConfig，基于包扫描Mapper，此时不需要配置**@Mapper**注解
@Configuration//必须在MyBatisConfig注册后再加载MapperScannerConfigurer，否则会报错@AutoConfigureAfter(MyBatisConfig.class)public class MyBatisMapperScannerConfig &#123;    @Bean    public MapperScannerConfigurer mapperScannerConfigurer() &#123;        MapperScannerConfigurer mapperScannerConfigurer = new MapperScannerConfigurer();        mapperScannerConfigurer.setSqlSessionFactoryBeanName(&quot;sqlSessionFactory&quot;);        mapperScannerConfigurer.setBasePackage(&quot;com.example.mapper&quot;);        return mapperScannerConfigurer;    &#125;&#125;
关闭DataSourceAutoConfiguration，因为这里我们配置了数据源，所以需要关闭该自动配置，另外，MybatisAutoConfiguration也是基于DataSourceAutoConfiguration的，所以关闭了DataSourceAutoConfiguration也就同时关闭了MybatisAutoConfiguration。

